const e={"es-first-u01.title":"Tiere","es-first-u01.tip":"Bilder anschauen, zuhören und zusammen nachsprechen. Lesen muss man noch nicht.","es-first-u01.w.0":"Katze","es-first-u01.w.1":"Hund","es-first-u01.w.2":"Fisch","es-first-u01.w.3":"Vogel","es-first-u01.w.4":"Kuh","es-first-u01.w.5":"Schwein","es-first-u02.title":"Essen","es-first-u02.tip":"Bilder anschauen, zuhören und zusammen nachsprechen. Lesen muss man noch nicht.","es-first-u02.w.0":"Apfel","es-first-u02.w.1":"Banane","es-first-u02.w.2":"Milch","es-first-u02.w.3":"Brot","es-first-u02.w.4":"Ei","es-first-u02.w.5":"Kuchen","es-first-u03.title":"Spielzeug","es-first-u03.tip":"Bilder anschauen, zuhören und zusammen nachsprechen. Lesen muss man noch nicht.","es-first-u03.w.0":"Ball","es-first-u03.w.1":"Auto","es-first-u03.w.2":"Teddybär","es-first-u03.w.3":"Drachen","es-first-u03.w.4":"Zug","es-first-u03.w.5":"Boot","es-first-u04.title":"Mein Körper","es-first-u04.tip":"Bilder anschauen, zuhören und zusammen nachsprechen. Lesen muss man noch nicht.","es-first-u04.w.0":"Auge","es-first-u04.w.1":"Ohr","es-first-u04.w.2":"Nase","es-first-u04.w.3":"Mund","es-first-u04.w.4":"Hand","es-first-u04.w.5":"Fuß","es-first-u05.title":"Farben","es-first-u05.tip":"Bilder anschauen, zuhören und zusammen nachsprechen. Lesen muss man noch nicht.","es-first-u05.w.0":"rot","es-first-u05.w.1":"blau","es-first-u05.w.2":"gelb","es-first-u05.w.3":"grün","es-first-u05.w.4":"schwarz","es-first-u05.w.5":"weiß","es-first-u06.title":"Familie","es-first-u06.tip":"Bilder anschauen, zuhören und zusammen nachsprechen. Lesen muss man noch nicht.","es-first-u06.w.0":"Mama","es-first-u06.w.1":"Papa","es-first-u06.w.2":"Baby","es-first-u06.w.3":"Junge","es-first-u06.w.4":"Mädchen","es-first-u06.w.5":"Oma","es-first-u07.title":"Zu Hause","es-first-u07.tip":"Bilder anschauen, zuhören und zusammen nachsprechen. Lesen muss man noch nicht.","es-first-u07.w.0":"Bett","es-first-u07.w.1":"Stuhl","es-first-u07.w.2":"Tür","es-first-u07.w.3":"Tasse","es-first-u07.w.4":"Buch","es-first-u07.w.5":"Uhr","es-first-u08.title":"Draußen","es-first-u08.tip":"Bilder anschauen, zuhören und zusammen nachsprechen. Lesen muss man noch nicht.","es-first-u08.w.0":"Sonne","es-first-u08.w.1":"Mond","es-first-u08.w.2":"Stern","es-first-u08.w.3":"Baum","es-first-u08.w.4":"Blume","es-first-u08.w.5":"Regen"},s={"es-kinder-u01.title":"Buchstaben A, B, C","es-kinder-u01.tip":"Sprich die spanischen Buchstabennamen wie ein kleines Lied nach: A heißt „a“, B heißt „be“, C heißt „ße“.","es-kinder-u01.w.0":"Baum","es-kinder-u01.w.1":"Biene","es-kinder-u01.w.2":"Wasser","es-kinder-u01.w.3":"Baby","es-kinder-u01.w.4":"Boot","es-kinder-u01.w.5":"Banane","es-kinder-u01.w.6":"Haus","es-kinder-u01.w.7":"Auto","es-kinder-u01.s.0":"A wie in árbol (Baum).","es-kinder-u01.s.1":"B wie in bebé (Baby).","es-kinder-u01.s.2":"C wie in casa (Haus).","es-kinder-u02.title":"Buchstaben D, E, F","es-kinder-u02.tip":"E spricht man „e“. Sucht zusammen Dinge bei euch zu Hause, die auf Spanisch mit D, E oder F anfangen.","es-kinder-u02.w.0":"Finger","es-kinder-u02.w.1":"Würfel","es-kinder-u02.w.2":"Delfin","es-kinder-u02.w.3":"Elefant","es-kinder-u02.w.4":"Stern","es-kinder-u02.w.5":"Blume","es-kinder-u02.w.6":"Erdbeere","es-kinder-u02.w.7":"Foto","es-kinder-u02.s.0":"D wie in dado (Würfel).","es-kinder-u02.s.1":"E wie in elefante (Elefant).","es-kinder-u02.s.2":"F wie in flor (Blume).","es-kinder-u03.title":"Buchstaben G, H, I","es-kinder-u03.tip":"Das spanische H ist stumm. huevo spricht man „ue-bo“.","es-kinder-u03.w.0":"Katze","es-kinder-u03.w.1":"Luftballon","es-kinder-u03.w.2":"Henne","es-kinder-u03.w.3":"Eis","es-kinder-u03.w.4":"Ei","es-kinder-u03.w.5":"Blatt","es-kinder-u03.w.6":"Insel","es-kinder-u03.w.7":"Magnet","es-kinder-u03.s.0":"G wie in gato (Katze).","es-kinder-u03.s.1":"H wie in huevo (Ei).","es-kinder-u03.s.2":"I wie in isla (Insel).","es-kinder-u04.title":"Buchstaben J, K, L","es-kinder-u04.tip":"J ist ein „ch“-Laut aus der Kehle, wie in „Bach“. jirafa klingt wie „chi-ra-fa“.","es-kinder-u04.w.0":"Giraffe","es-kinder-u04.w.1":"Saft","es-kinder-u04.w.2":"Seife","es-kinder-u04.w.3":"Koala","es-kinder-u04.w.4":"Kiwi","es-kinder-u04.w.5":"Mond","es-kinder-u04.w.6":"Löwe","es-kinder-u04.w.7":"Buch","es-kinder-u04.s.0":"J wie in jirafa (Giraffe).","es-kinder-u04.s.1":"K wie in koala (Koala).","es-kinder-u04.s.2":"L wie in luna (Mond).","es-kinder-u05.title":"Buchstaben M, N, Ñ","es-kinder-u05.tip":"Ñ gibt es nur im Spanischen. Es klingt wie „nj“. niño spricht man „ni-njo“!","es-kinder-u05.w.0":"Hand","es-kinder-u05.w.1":"Apfel","es-kinder-u05.w.2":"Affe","es-kinder-u05.w.3":"Wolke","es-kinder-u05.w.4":"Nase","es-kinder-u05.w.5":"Schnee","es-kinder-u05.w.6":"Junge","es-kinder-u05.w.7":"Gnu","es-kinder-u05.s.0":"M wie in mano (Hand).","es-kinder-u05.s.1":"N wie in nube (Wolke).","es-kinder-u05.s.2":"Ñ wie in ñu (Gnu).","es-kinder-u06.title":"Buchstaben O, P, Q","es-kinder-u06.tip":"Nach Q kommt immer ein u, und es klingt wie „k“. queso spricht man „ke-so“.","es-kinder-u06.w.0":"Bär","es-kinder-u06.w.1":"Auge","es-kinder-u06.w.2":"Schaf","es-kinder-u06.w.3":"Brot","es-kinder-u06.w.4":"Ente","es-kinder-u06.w.5":"Ball","es-kinder-u06.w.6":"Fisch","es-kinder-u06.w.7":"Käse","es-kinder-u06.s.0":"O wie in oso (Bär).","es-kinder-u06.s.1":"P wie in pan (Brot).","es-kinder-u06.s.2":"Q wie in queso (Käse).","es-kinder-u07.title":"Buchstaben R, S, T","es-kinder-u07.tip":"Das R wird mit der Zunge gerollt: „rrr“. Wenn das schwer ist, darf es erst mal ein weiches „r“ sein.","es-kinder-u07.w.0":"Maus","es-kinder-u07.w.1":"Frosch","es-kinder-u07.w.2":"Sonne","es-kinder-u07.w.3":"Suppe","es-kinder-u07.w.4":"Stuhl","es-kinder-u07.w.5":"Zug","es-kinder-u07.w.6":"Tomate","es-kinder-u07.w.7":"Schildkröte","es-kinder-u07.s.0":"R wie in rana (Frosch).","es-kinder-u07.s.1":"S wie in sol (Sonne).","es-kinder-u07.s.2":"T wie in tren (Zug).","es-kinder-u08.title":"Buchstaben U bis Z","es-kinder-u08.tip":"V klingt genau wie B: „b“. Z klingt wie ein weiches „ß“. Jetzt kennst du alle Buchstaben!","es-kinder-u08.w.0":"Traube","es-kinder-u08.w.1":"eins","es-kinder-u08.w.2":"Kuh","es-kinder-u08.w.3":"Glas","es-kinder-u08.w.4":"Jo-Jo","es-kinder-u08.w.5":"Jacht","es-kinder-u08.w.6":"Schuh","es-kinder-u08.w.7":"Karotte","es-kinder-u08.s.0":"U wie in uva (Traube).","es-kinder-u08.s.1":"V wie in vaca (Kuh).","es-kinder-u08.s.2":"Z wie in zapato (Schuh)."},n={"es-g12-u01.title":"Begrüßungen","es-g12-u01.tip":"Im Spanischen steht am Satzanfang auch ein Ausrufe- oder Fragezeichen, aber auf dem Kopf (¡ ¿). Lustig, oder?","es-g12-u01.w.0":"Hallo","es-g12-u01.w.1":"Tschüss","es-g12-u01.w.2":"Danke","es-g12-u01.w.3":"Bitte","es-g12-u01.w.4":"Ja","es-g12-u01.w.5":"Nein","es-g12-u01.w.6":"Freund","es-g12-u01.w.7":"Guten Morgen","es-g12-u01.w.8":"Gute Nacht","es-g12-u01.s.0":"Hallo, Freund!","es-g12-u01.s.1":"Guten Morgen, Mama.","es-g12-u01.s.2":"Danke, bitte.","es-g12-u01.s.3":"Ja, danke.","es-g12-u01.s.4":"Nein, danke.","es-g12-u01.s.5":"Gute Nacht, tschüss.","es-g12-u02.title":"Zahlen 1 bis 10","es-g12-u02.tip":"Streck die Finger einen nach dem anderen aus und zähle von uno bis diez.","es-g12-u02.w.0":"eins","es-g12-u02.w.1":"zwei","es-g12-u02.w.2":"drei","es-g12-u02.w.3":"vier","es-g12-u02.w.4":"fünf","es-g12-u02.w.5":"sechs","es-g12-u02.w.6":"sieben","es-g12-u02.w.7":"acht","es-g12-u02.w.8":"neun","es-g12-u02.w.9":"zehn","es-g12-u02.s.0":"Eins, zwei, drei.","es-g12-u02.s.1":"Ich bin fünf Jahre alt.","es-g12-u02.s.2":"Vier plus vier ist acht.","es-g12-u02.s.3":"Ich habe zwei Hände.","es-g12-u02.s.4":"Zehn Finger.","es-g12-u02.s.5":"Sechs, sieben, acht, neun, zehn.","es-g12-u03.title":"Farben","es-g12-u03.tip":"Die Farbe steht hinter dem Wort, das sie beschreibt: „manzana roja“ (roter Apfel). Nach einem weiblichen Wort wird aus -o ein -a.","es-g12-u03.w.0":"rot","es-g12-u03.w.1":"blau","es-g12-u03.w.2":"gelb","es-g12-u03.w.3":"grün","es-g12-u03.w.4":"weiß","es-g12-u03.w.5":"schwarz","es-g12-u03.w.6":"rosa","es-g12-u03.w.7":"orange","es-g12-u03.w.8":"lila","es-g12-u03.s.0":"Die Sonne ist gelb.","es-g12-u03.s.1":"Der Apfel ist rot.","es-g12-u03.s.2":"Das Meer ist blau.","es-g12-u03.s.3":"Ich mag Grün.","es-g12-u03.s.4":"Meine Katze ist schwarz.","es-g12-u03.s.5":"Die Blume ist rosa.","es-g12-u04.title":"Familie","es-g12-u04.tip":"Bei mamá und papá betont man das Ende: „ma-MA“, „pa-PA“. Der Akzent (´) zeigt dir, wo du Kraft gibst.","es-g12-u04.w.0":"Mama","es-g12-u04.w.1":"Papa","es-g12-u04.w.2":"Bruder","es-g12-u04.w.3":"Schwester","es-g12-u04.w.4":"Oma","es-g12-u04.w.5":"Opa","es-g12-u04.w.6":"Baby","es-g12-u04.w.7":"Familie","es-g12-u04.w.8":"Hund","es-g12-u04.s.0":"Das ist meine Mama.","es-g12-u04.s.1":"Mein Papa ist groß.","es-g12-u04.s.2":"Ich habe eine kleine Schwester.","es-g12-u04.s.3":"Meine Oma ist lieb.","es-g12-u04.s.4":"Das Baby schläft.","es-g12-u04.s.5":"Meine Familie ist groß.","es-g12-u05.title":"Tiere","es-g12-u05.tip":"Vor ein Tier kommt el oder la, zum Beispiel el gato, la vaca.","es-g12-u05.w.0":"Katze","es-g12-u05.w.1":"Vogel","es-g12-u05.w.2":"Fisch","es-g12-u05.w.3":"Pferd","es-g12-u05.w.4":"Kuh","es-g12-u05.w.5":"Schwein","es-g12-u05.w.6":"Hase","es-g12-u05.w.7":"Bär","es-g12-u05.w.8":"Löwe","es-g12-u05.s.0":"Die Katze ist klein.","es-g12-u05.s.1":"Der Löwe ist groß.","es-g12-u05.s.2":"Die Kuh frisst Gras.","es-g12-u05.s.3":"Der Vogel singt.","es-g12-u05.s.4":"Ich mag den Hasen.","es-g12-u05.s.5":"Das Pferd läuft schnell.","es-g12-u06.title":"Obst","es-g12-u06.tip":"„Me gusta“ heißt „ich mag“. Setz dein Lieblingsobst dahinter und sag es laut.","es-g12-u06.w.0":"Apfel","es-g12-u06.w.1":"Banane","es-g12-u06.w.2":"Erdbeere","es-g12-u06.w.3":"Traube","es-g12-u06.w.4":"Birne","es-g12-u06.w.5":"Wassermelone","es-g12-u06.w.6":"Zitrone","es-g12-u06.w.7":"Pfirsich","es-g12-u06.w.8":"Kirsche","es-g12-u06.s.0":"Ich mag Erdbeeren.","es-g12-u06.s.1":"Die Wassermelone ist groß.","es-g12-u06.s.2":"Ich möchte einen Apfel.","es-g12-u06.s.3":"Die Zitrone ist gelb.","es-g12-u06.s.4":"Trauben sind süß.","es-g12-u06.s.5":"Eine Banane, bitte.","es-g12-u07.title":"Essen","es-g12-u07.tip":"como heißt „ich esse“, bebo heißt „ich trinke“. Probier es beim Essen aus.","es-g12-u07.w.0":"Brot","es-g12-u07.w.1":"Reis","es-g12-u07.w.2":"Milch","es-g12-u07.w.3":"Wasser","es-g12-u07.w.4":"Käse","es-g12-u07.w.5":"Ei","es-g12-u07.w.6":"Suppe","es-g12-u07.w.7":"Hähnchen","es-g12-u07.w.8":"Pizza","es-g12-u07.s.0":"Ich möchte Brot und Käse.","es-g12-u07.s.1":"Ich trinke Milch.","es-g12-u07.s.2":"Die Suppe ist heiß.","es-g12-u07.s.3":"Ich esse Reis mit Hähnchen.","es-g12-u07.s.4":"Wasser, bitte.","es-g12-u07.s.5":"Ich mag Pizza.","es-g12-u08.title":"Mein Körper","es-g12-u08.tip":"„Me duele“ heißt „mir tut ... weh“. Setz die Stelle ein, die wehtut: Me duele la mano.","es-g12-u08.w.0":"Kopf","es-g12-u08.w.1":"Auge","es-g12-u08.w.2":"Nase","es-g12-u08.w.3":"Mund","es-g12-u08.w.4":"Ohr","es-g12-u08.w.5":"Hand","es-g12-u08.w.6":"Fuß","es-g12-u08.w.7":"Haare","es-g12-u08.w.8":"Zahn","es-g12-u08.s.0":"Ich habe zwei Augen.","es-g12-u08.s.1":"Meine Haare sind schwarz.","es-g12-u08.s.2":"Fass deine Nase an.","es-g12-u08.s.3":"Mir tut der Kopf weh.","es-g12-u08.s.4":"Ich wasche mir die Hände.","es-g12-u08.s.5":"Mach den Mund auf.","es-g12-u09.title":"Schule","es-g12-u09.tip":"„Voy a“ heißt „ich gehe zu/nach“: Voy a la escuela, voy a casa.","es-g12-u09.w.0":"Schule","es-g12-u09.w.1":"Buch","es-g12-u09.w.2":"Bleistift","es-g12-u09.w.3":"Schulranzen","es-g12-u09.w.4":"Schreibtisch","es-g12-u09.w.5":"Lehrerin","es-g12-u09.w.6":"Papier","es-g12-u09.w.7":"Schere","es-g12-u09.w.8":"Tafel","es-g12-u09.s.0":"Ich gehe zur Schule.","es-g12-u09.s.1":"Ich habe einen Bleistift.","es-g12-u09.s.2":"Das Buch liegt auf dem Schreibtisch.","es-g12-u09.s.3":"Mein Schulranzen ist blau.","es-g12-u09.s.4":"Die Lehrerin ist nett.","es-g12-u09.s.5":"Gib mir bitte das Papier.","es-g12-u10.title":"Mein Zuhause","es-g12-u10.tip":"„está en“ heißt „ist in/auf“. Sag, wo die Dinge sind.","es-g12-u10.w.0":"Haus","es-g12-u10.w.1":"Tür","es-g12-u10.w.2":"Fenster","es-g12-u10.w.3":"Bett","es-g12-u10.w.4":"Küche","es-g12-u10.w.5":"Badezimmer","es-g12-u10.w.6":"Sofa","es-g12-u10.w.7":"Lampe","es-g12-u10.w.8":"Garten","es-g12-u10.s.0":"Unser Haus ist klein.","es-g12-u10.s.1":"Mach die Tür auf.","es-g12-u10.s.2":"Ich schlafe in meinem Bett.","es-g12-u10.s.3":"Mama ist in der Küche.","es-g12-u10.s.4":"Die Katze ist auf dem Sofa.","es-g12-u10.s.5":"Im Garten sind Blumen.","es-g12-u11.title":"Kleidung","es-g12-u11.tip":"„Me pongo“ heißt „ich ziehe ... an“. Sag es morgens beim Anziehen.","es-g12-u11.w.0":"T-Shirt","es-g12-u11.w.1":"Hose","es-g12-u11.w.2":"Schuhe","es-g12-u11.w.3":"Mütze","es-g12-u11.w.4":"Kleid","es-g12-u11.w.5":"Mantel","es-g12-u11.w.6":"Socken","es-g12-u11.w.7":"Schal","es-g12-u11.w.8":"Handschuhe","es-g12-u11.s.0":"Ich ziehe mein T-Shirt an.","es-g12-u11.s.1":"Meine Schuhe sind rot.","es-g12-u11.s.2":"Es ist kalt, zieh den Mantel an.","es-g12-u11.s.3":"Ich mag dieses Kleid.","es-g12-u11.s.4":"Wo ist meine Mütze?","es-g12-u11.s.5":"Die Socken sind blau.","es-g12-u12.title":"Wetter","es-g12-u12.tip":"Das Wetter sagt man mit hace: Hace sol (die Sonne scheint), Hace frío (es ist kalt), Hace calor (es ist heiß).","es-g12-u12.w.0":"Sonne","es-g12-u12.w.1":"Regen","es-g12-u12.w.2":"Schnee","es-g12-u12.w.3":"Wind","es-g12-u12.w.4":"Wolke","es-g12-u12.w.5":"Hitze","es-g12-u12.w.6":"Kälte","es-g12-u12.w.7":"Regenschirm","es-g12-u12.w.8":"Regenbogen","es-g12-u12.s.0":"Die Sonne scheint hell.","es-g12-u12.s.1":"Heute ist es kalt.","es-g12-u12.s.2":"Es regnet viel.","es-g12-u12.s.3":"Auf dem Berg liegt Schnee.","es-g12-u12.s.4":"Es ist sehr heiß.","es-g12-u12.s.5":"Schau, der Regenbogen!","es-g12-u13.title":"Wochentage und der Tag","es-g12-u13.tip":"Wochentage schreibt man im Spanischen klein. mañana heißt „morgen“ und auch „Morgen“ (die Zeit am Vormittag).","es-g12-u13.w.0":"Montag","es-g12-u13.w.1":"Dienstag","es-g12-u13.w.2":"Samstag","es-g12-u13.w.3":"Sonntag","es-g12-u13.w.4":"heute","es-g12-u13.w.5":"morgen","es-g12-u13.w.6":"Nacht","es-g12-u13.w.7":"Nachmittag","es-g12-u13.w.8":"Woche","es-g12-u13.s.0":"Heute ist Montag.","es-g12-u13.s.1":"Morgen ist Dienstag.","es-g12-u13.s.2":"Am Samstag ist keine Schule.","es-g12-u13.s.3":"Guten Tag (am Nachmittag).","es-g12-u13.s.4":"Nachts schlafe ich.","es-g12-u13.s.5":"Am Sonntag spiele ich mit Papa.","es-g12-u14.title":"Fahrzeuge","es-g12-u14.tip":"„Voy en“ heißt „ich fahre mit“: voy en tren, voy en coche.","es-g12-u14.w.0":"Auto","es-g12-u14.w.1":"Bus","es-g12-u14.w.2":"Zug","es-g12-u14.w.3":"Fahrrad","es-g12-u14.w.4":"Flugzeug","es-g12-u14.w.5":"Schiff","es-g12-u14.w.6":"Motorrad","es-g12-u14.w.7":"Taxi","es-g12-u14.w.8":"Lastwagen","es-g12-u14.s.0":"Ich fahre mit dem Bus.","es-g12-u14.s.1":"Der Zug ist schnell.","es-g12-u14.s.2":"Ich habe ein rotes Fahrrad.","es-g12-u14.s.3":"Das Flugzeug fliegt hoch.","es-g12-u14.s.4":"Das Schiff ist auf dem Meer.","es-g12-u14.s.5":"Papa hat ein Auto.","es-g12-u15.title":"Spielzeug und Spielen","es-g12-u15.tip":"„Vamos a“ heißt „lass uns ... gehen“ oder „lass uns ... machen“. Sag zu einem Freund: Vamos al parque!","es-g12-u15.w.0":"Ball","es-g12-u15.w.1":"Puppe","es-g12-u15.w.2":"Teddybär","es-g12-u15.w.3":"Spielzeugauto","es-g12-u15.w.4":"Puzzle","es-g12-u15.w.5":"Drachen","es-g12-u15.w.6":"Luftballon","es-g12-u15.w.7":"Spiel","es-g12-u15.w.8":"Spielplatz","es-g12-u15.s.0":"Ich spiele mit dem Ball.","es-g12-u15.s.1":"Meine Puppe ist hübsch.","es-g12-u15.s.2":"Lass uns auf den Spielplatz gehen.","es-g12-u15.s.3":"Der Luftballon ist rot.","es-g12-u15.s.4":"Ich mag dieses Spiel.","es-g12-u15.s.5":"Der Drachen fliegt.","es-g12-u16.title":"Natur","es-g12-u16.tip":"„Veo“ heißt „ich sehe“. Geh nach draußen und sag, was du siehst.","es-g12-u16.w.0":"Baum","es-g12-u16.w.1":"Blume","es-g12-u16.w.2":"Fluss","es-g12-u16.w.3":"Berg","es-g12-u16.w.4":"Meer","es-g12-u16.w.5":"Mond","es-g12-u16.w.6":"Stern","es-g12-u16.w.7":"Stein","es-g12-u16.w.8":"Gras","es-g12-u16.s.0":"Der Baum ist hoch.","es-g12-u16.s.1":"Der Mond ist weiß.","es-g12-u16.s.2":"Ich sehe einen Stern.","es-g12-u16.s.3":"Der Fluss ist lang.","es-g12-u16.s.4":"Auf dem Berg sind Blumen.","es-g12-u16.s.5":"Ich mag das Meer.","es-g12-u17.title":"Gefühle","es-g12-u17.tip":"Gefühle sagt man mit estoy: Estoy feliz. Mädchen sagen cansada, enfadada – mit -a am Ende.","es-g12-u17.w.0":"glücklich","es-g12-u17.w.1":"traurig","es-g12-u17.w.2":"wütend","es-g12-u17.w.3":"müde","es-g12-u17.w.4":"ängstlich","es-g12-u17.w.5":"froh","es-g12-u17.w.6":"gelangweilt","es-g12-u17.w.7":"überrascht","es-g12-u17.w.8":"krank","es-g12-u17.s.0":"Ich bin glücklich.","es-g12-u17.s.1":"Bist du traurig?","es-g12-u17.s.2":"Ich bin sehr müde.","es-g12-u17.s.3":"Mein Bruder ist wütend.","es-g12-u17.s.4":"Ich habe keine Angst.","es-g12-u17.s.5":"Ich bin heute krank.","es-g12-u18.title":"Tätigkeiten","es-g12-u18.tip":"Wörter, die auf -ar, -er oder -ir enden, sind Tätigkeitswörter. Du kannst sie direkt hinter „Me gusta“ setzen.","es-g12-u18.w.0":"laufen","es-g12-u18.w.1":"springen","es-g12-u18.w.2":"essen","es-g12-u18.w.3":"trinken","es-g12-u18.w.4":"schlafen","es-g12-u18.w.5":"lesen","es-g12-u18.w.6":"singen","es-g12-u18.w.7":"tanzen","es-g12-u18.w.8":"schwimmen","es-g12-u18.s.0":"Ich laufe gern.","es-g12-u18.s.1":"Ich möchte essen.","es-g12-u18.s.2":"Lass uns schwimmen gehen.","es-g12-u18.s.3":"Sie singt gut.","es-g12-u18.s.4":"Ich lese ein Buch.","es-g12-u18.s.5":"Der Hund springt.","es-g12-u19.title":"Unser Viertel","es-g12-u19.tip":"„Hay“ heißt „es gibt“. Sag beim Spazierengehen: Hay una tienda, hay un parque.","es-g12-u19.w.0":"Straße","es-g12-u19.w.1":"Laden","es-g12-u19.w.2":"Park","es-g12-u19.w.3":"Krankenhaus","es-g12-u19.w.4":"Bücherei","es-g12-u19.w.5":"Bäckerei","es-g12-u19.w.6":"Markt","es-g12-u19.w.7":"Kirche","es-g12-u19.w.8":"Ampel","es-g12-u19.s.0":"Ich wohne in dieser Straße.","es-g12-u19.s.1":"Ich gehe in den Laden.","es-g12-u19.s.2":"Die Bücherei ist nah.","es-g12-u19.s.3":"Ich kaufe Brot in der Bäckerei.","es-g12-u19.s.4":"Die Ampel ist rot.","es-g12-u19.s.5":"Hier gibt es einen Park.","es-g12-u20.title":"Geburtstagsfeier","es-g12-u20.tip":"„¡Feliz cumpleaños!“ heißt „Alles Gute zum Geburtstag!“. Sag es unbedingt, wenn ein Freund Geburtstag hat.","es-g12-u20.w.0":"Geburtstag","es-g12-u20.w.1":"Geschenk","es-g12-u20.w.2":"Kuchen","es-g12-u20.w.3":"Kerze","es-g12-u20.w.4":"Party","es-g12-u20.w.5":"Lied","es-g12-u20.w.6":"Freunde","es-g12-u20.w.7":"Partyhut","es-g12-u20.w.8":"Eis","es-g12-u20.s.0":"Alles Gute zum Geburtstag!","es-g12-u20.s.1":"Heute ist meine Party.","es-g12-u20.s.2":"Ich habe ein Geschenk für dich.","es-g12-u20.s.3":"Puste die Kerzen aus.","es-g12-u20.s.4":"Wir singen ein Lied.","es-g12-u20.s.5":"Meine Freunde essen Kuchen."},i={"es-g34-u01.title":"Ich bin: sich vorstellen","es-g34-u01.tip":"Im Spanischen lässt man das Subjekt oft weg. Schon „Soy Lucía“ heißt „Ich bin Lucía“.","es-g34-u01.w.0":"Schüler","es-g34-u01.w.1":"Lehrerin","es-g34-u01.w.2":"Arzt","es-g34-u01.w.3":"Koch","es-g34-u01.w.4":"nett","es-g34-u01.w.5":"groß","es-g34-u01.w.6":"klein","es-g34-u01.w.7":"klug","es-g34-u01.w.8":"Name","es-g34-u01.w.9":"Land","es-g34-u01.s.0":"Ich bin Lucía.","es-g34-u01.s.1":"Ich komme aus Peru.","es-g34-u01.s.2":"Du bist mein Freund.","es-g34-u01.s.3":"Er ist Arzt.","es-g34-u01.s.4":"Sie ist sehr klug.","es-g34-u01.s.5":"Wir sind Schüler.","es-g34-u01.s.6":"Meine Lehrerin ist nett.","es-g34-u01.s.7":"Wie heißt du?","es-g34-u01.g.title":"Das Verb ser: soy, eres, es","es-g34-u01.g.x.0":"„Sein“ heißt ser. Die Form ändert sich je nach Person: yo soy, tú eres, él/ella es.","es-g34-u01.g.x.1":"Bei mehreren: nosotros somos, ellos son.","es-g34-u01.g.x.2":"Ser benutzt du für Namen, Beruf, Land und Charakter: Soy estudiante. Es de México.","es-g34-u01.g.0":"Ich bin Schüler.","es-g34-u01.g.1":"Du bist groß.","es-g34-u01.g.2":"Sie ist Lehrerin.","es-g34-u01.g.3":"Wir sind Freunde.","es-g34-u01.g.4":"Sie kommen aus Spanien.","es-g34-u01.g.5":"Du bist mein Freund.","es-g34-u01.g.5.task":"Ändere den Satz so, dass er mit „Tú“ beginnt","es-g34-u01.g.6":"Sie ist klug.","es-g34-u01.g.6.task":"Ändere den Satz so, dass er mit „Ella“ beginnt","es-g34-u01.g.7":"Wir sind Schüler.","es-g34-u01.g.7.task":"Ändere den Satz so, dass er mit „Nosotros“ beginnt","es-g34-u01.st.title":"Ein neuer Freund","es-g34-u01.st.l.0":"Hallo! Ich bin Lucía. Wie heißt du?","es-g34-u01.st.l.1":"Ich heiße Mateo. Ich komme aus Mexiko.","es-g34-u01.st.l.2":"Ich komme aus Peru. Ich bin Schülerin.","es-g34-u01.st.l.3":"Ich auch. Meine Mama ist Ärztin.","es-g34-u01.st.l.4":"Toll! Mein Papa ist Koch.","es-g34-u01.st.l.5":"Du bist sehr nett, Lucía.","es-g34-u01.st.q.0":"Woher kommt Mateo?","es-g34-u01.st.q.0.o.0":"Aus Mexiko","es-g34-u01.st.q.0.o.1":"Aus Peru","es-g34-u01.st.q.0.o.2":"Aus Spanien","es-g34-u01.st.q.1":"Was macht Lucías Papa beruflich?","es-g34-u01.st.q.1.o.0":"Arzt","es-g34-u01.st.q.1.o.1":"Koch","es-g34-u01.st.q.1.o.2":"Lehrer","es-g34-u02.title":"Wo bist du? Wie geht es dir?","es-g34-u02.tip":"Gefühle sagt man mit estar: Estoy feliz, estoy cansado. Mädchen sagen contenta, nerviosa – mit -a am Ende.","es-g34-u02.w.0":"hier","es-g34-u02.w.1":"dort","es-g34-u02.w.2":"nah","es-g34-u02.w.3":"weit weg","es-g34-u02.w.4":"froh","es-g34-u02.w.5":"nervös","es-g34-u02.w.6":"beschäftigt","es-g34-u02.w.7":"bereit","es-g34-u02.w.8":"oben auf","es-g34-u02.w.9":"unter","es-g34-u02.s.0":"Ich bin zu Hause.","es-g34-u02.s.1":"Wo bist du?","es-g34-u02.s.2":"Das Buch liegt auf dem Tisch.","es-g34-u02.s.3":"Mama ist beschäftigt.","es-g34-u02.s.4":"Wir sind sehr froh.","es-g34-u02.s.5":"Die Schule ist nah.","es-g34-u02.s.6":"Ich bin ein bisschen nervös.","es-g34-u02.s.7":"Bist du bereit?","es-g34-u02.g.title":"Das Verb estar: Ort und Gefühl","es-g34-u02.g.x.0":"Wo etwas ist und wie man sich gerade fühlt, sagt man mit estar: estoy, estás, está, estamos, están.","es-g34-u02.g.x.1":"Estoy en casa. (Ich bin zu Hause.) / Está contento. (Er ist froh.)","es-g34-u02.g.x.2":"Ser ist „so ist es immer“, estar ist „so ist es gerade“ oder „da ist es“.","es-g34-u02.g.0":"Ich bin in der Schule.","es-g34-u02.g.1":"Bist du froh?","es-g34-u02.g.2":"Die Katze ist unter dem Stuhl.","es-g34-u02.g.3":"Wir sind bereit.","es-g34-u02.g.4":"Sie sind weit weg.","es-g34-u02.g.5":"Sie ist nervös.","es-g34-u02.g.5.task":"Ändere den Satz so, dass er mit „Ella“ beginnt","es-g34-u02.g.6":"Wo bist du?","es-g34-u02.g.6.task":"Mach daraus eine Frage mit „¿Dónde…?“","es-g34-u02.g.7":"Wir sind zu Hause.","es-g34-u02.g.7.task":"Ändere den Satz so, dass er mit „Nosotros“ beginnt","es-g34-u03.title":"El und la: das Geschlecht der Wörter","es-g34-u03.tip":"Lerne bei jedem neuen Wort gleich el oder la mit. Nicht „mesa“, sondern „la mesa“!","es-g34-u03.w.0":"kleiner Junge","es-g34-u03.w.1":"kleines Mädchen","es-g34-u03.w.2":"Junge","es-g34-u03.w.3":"Mädchen","es-g34-u03.w.4":"Heft","es-g34-u03.w.5":"Fenster","es-g34-u03.w.6":"Dorf","es-g34-u03.w.7":"Stadt","es-g34-u03.w.8":"Hand","es-g34-u03.w.9":"Problem","es-g34-u03.s.0":"Der Junge hat ein Heft.","es-g34-u03.s.1":"Das Mädchen öffnet das Fenster.","es-g34-u03.s.2":"Die Jungen spielen Fußball.","es-g34-u03.s.3":"Die Mädchen singen ein Lied.","es-g34-u03.s.4":"Die Stadt ist sehr groß.","es-g34-u03.s.5":"Das Dorf ist klein und schön.","es-g34-u03.s.6":"Die Hand hat fünf Finger.","es-g34-u03.s.7":"Das Problem ist schwer.","es-g34-u03.g.title":"Die Artikel el / la / los / las","es-g34-u03.g.x.0":"Spanische Nomen sind männlich oder weiblich. Meist ist -o männlich (el niño) und -a weiblich (la niña).","es-g34-u03.g.x.1":"In der Mehrzahl: los, las – los niños, las niñas.","es-g34-u03.g.x.2":"Es gibt Ausnahmen: la mano (weiblich), el problema (männlich). Lerne den Artikel immer mit dem Wort.","es-g34-u03.g.0":"Der Junge isst Brot.","es-g34-u03.g.1":"Das Mädchen hat eine Katze.","es-g34-u03.g.2":"Die Jungen sind im Park.","es-g34-u03.g.3":"Die Fenster sind offen.","es-g34-u03.g.3.task":"Mach daraus die Mehrzahl","es-g34-u03.g.4":"Die Hand ist klein.","es-g34-u03.g.5":"Das Problem ist leicht.","es-g34-u03.g.6":"Die Kinder spielen.","es-g34-u03.g.6.task":"Mach daraus die Mehrzahl","es-g34-u03.g.7":"Die Mädchen singen.","es-g34-u03.g.7.task":"Mach daraus die Mehrzahl","es-g34-u03.st.title":"Im Klassenzimmer","es-g34-u03.st.l.0":"Guten Morgen, Kinder. Öffnet eure Hefte.","es-g34-u03.st.l.1":"Frau Lehrerin, ich habe mein Heft nicht.","es-g34-u03.st.l.2":"Wo ist dein Heft, Diego?","es-g34-u03.st.l.3":"Zu Hause, auf dem Tisch.","es-g34-u03.st.l.4":"Ich habe zwei Hefte. Nimm eins.","es-g34-u03.st.l.5":"Danke, Ana! Du bist sehr lieb.","es-g34-u03.st.q.0":"Wo ist Diegos Heft?","es-g34-u03.st.q.0.o.0":"In der Schule","es-g34-u03.st.q.0.o.1":"Zu Hause auf dem Tisch","es-g34-u03.st.q.0.o.2":"In seiner Tasche","es-g34-u03.st.q.1":"Wer leiht ein Heft aus?","es-g34-u03.st.q.1.o.0":"Die Lehrerin","es-g34-u03.st.q.1.o.1":"Diego","es-g34-u03.st.q.1.o.2":"Ana","es-g34-u04.title":"Roter Apfel, rote Äpfel: Eigenschaftswörter","es-g34-u04.tip":"Endet das Nomen auf -a, endet auch das Eigenschaftswort auf -a. Ist das Nomen in der Mehrzahl, bekommt das Eigenschaftswort auch ein -s. Wie Paare, die zusammenpassen.","es-g34-u04.w.0":"groß","es-g34-u04.w.1":"klein","es-g34-u04.w.2":"schön","es-g34-u04.w.3":"hässlich","es-g34-u04.w.4":"neu","es-g34-u04.w.5":"alt","es-g34-u04.w.6":"schnell","es-g34-u04.w.7":"langsam","es-g34-u04.w.8":"sauber","es-g34-u04.w.9":"schmutzig","es-g34-u04.s.0":"Der Apfel ist rot.","es-g34-u04.s.1":"Die Äpfel sind rot.","es-g34-u04.s.2":"Das neue Auto ist schnell.","es-g34-u04.s.3":"Mein Haus ist klein und schön.","es-g34-u04.s.4":"Die alten Bücher sind schmutzig.","es-g34-u04.s.5":"Die Schildkröte ist langsam.","es-g34-u04.s.6":"Meine Schuhe sind sauber.","es-g34-u04.s.7":"Der große Hund ist hässlich.","es-g34-u04.g.title":"Angleichung der Adjektive: -o/-a, -os/-as","es-g34-u04.g.x.0":"Eigenschaftswörter (Adjektive) passen sich dem Nomen an: el niño alto, la niña alta.","es-g34-u04.g.x.1":"In der Mehrzahl kommt ein -s dazu: los niños altos, las niñas altas.","es-g34-u04.g.x.2":"Adjektive auf -e wie grande oder inteligente bleiben für männlich und weiblich gleich: el niño grande, la niña grande.","es-g34-u04.g.x.3":"Das Adjektiv steht meistens hinter dem Nomen: la casa bonita.","es-g34-u04.g.0":"Das Haus ist schön.","es-g34-u04.g.1":"Das Auto ist neu.","es-g34-u04.g.2":"Die Hunde sind schnell.","es-g34-u04.g.3":"Die Mädchen sind klug.","es-g34-u04.g.4":"Die Schildkröte ist langsam.","es-g34-u04.g.5":"Die Äpfel sind rot.","es-g34-u04.g.5.task":"Mach daraus die Mehrzahl","es-g34-u04.g.6":"Der Rucksack ist neu.","es-g34-u04.g.6.task":"Schreib den Satz mit „La mochila“","es-g34-u04.g.7":"Die Katzen sind klein.","es-g34-u04.g.7.task":"Mach daraus die Mehrzahl","es-g34-u05.title":"Verben auf -ar: hablo, hablas, habla","es-g34-u05.tip":"-o (ich), -as (du), -a (er/sie), -amos (wir), -an (sie). Schon an der Endung siehst du, wer etwas tut!","es-g34-u05.w.0":"sprechen","es-g34-u05.w.1":"lernen","es-g34-u05.w.2":"zuhören","es-g34-u05.w.3":"gehen","es-g34-u05.w.4":"kochen","es-g34-u05.w.5":"zeichnen","es-g34-u05.w.6":"arbeiten","es-g34-u05.w.7":"schwimmen","es-g34-u05.w.8":"Musik","es-g34-u05.w.9":"Schwimmbad","es-g34-u05.s.0":"Ich spreche Spanisch.","es-g34-u05.s.1":"Du lernst viel.","es-g34-u05.s.2":"Sie hört Musik.","es-g34-u05.s.3":"Wir gehen zum Park.","es-g34-u05.s.4":"Mein Papa kocht das Abendessen.","es-g34-u05.s.5":"Die Kinder zeichnen Tiere.","es-g34-u05.s.6":"Mama arbeitet montags.","es-g34-u05.s.7":"Wir schwimmen im Schwimmbad.","es-g34-u05.g.title":"Regelmäßige Verben auf -ar im Präsens","es-g34-u05.g.x.0":"Bei Verben auf -ar nimmst du das -ar weg und hängst die Endung für die Person an: habl-o, habl-as, habl-a, habl-amos, habl-an.","es-g34-u05.g.x.1":"yo hablo (ich spreche), tú hablas (du), él/ella habla (er/sie), nosotros hablamos (wir), ellos hablan (sie).","es-g34-u05.g.x.2":"Estudiar, caminar und cocinar ändern sich genauso.","es-g34-u05.g.0":"Ich rede mit meiner Oma.","es-g34-u05.g.1":"Du gehst schnell.","es-g34-u05.g.2":"Sie zeichnet sehr gut.","es-g34-u05.g.3":"Wir schwimmen jeden Samstag.","es-g34-u05.g.4":"Sie hören der Lehrerin zu.","es-g34-u05.g.5":"Sie lernt Englisch.","es-g34-u05.g.5.task":"Ändere den Satz so, dass er mit „Ella“ beginnt","es-g34-u05.g.6":"Wir arbeiten zu Hause.","es-g34-u05.g.6.task":"Ändere den Satz so, dass er mit „Nosotros“ beginnt","es-g34-u05.g.7":"Du kochst das Abendessen.","es-g34-u05.g.7.task":"Ändere den Satz so, dass er mit „Tú“ beginnt","es-g34-u06.title":"Verben auf -er und -ir: como, vivo","es-g34-u06.tip":"-er und -ir sind fast gleich. Nur bei „wir“ ist es anders: comemos / vivimos.","es-g34-u06.w.0":"essen","es-g34-u06.w.1":"trinken","es-g34-u06.w.2":"lesen","es-g34-u06.w.3":"lernen","es-g34-u06.w.4":"rennen","es-g34-u06.w.5":"wohnen","es-g34-u06.w.6":"schreiben","es-g34-u06.w.7":"öffnen","es-g34-u06.w.8":"Brief","es-g34-u06.w.9":"Geschichte (Märchen)","es-g34-u06.s.0":"Ich esse Reis.","es-g34-u06.s.1":"Du trinkst Milch.","es-g34-u06.s.2":"Sie liest eine Geschichte.","es-g34-u06.s.3":"Wir lernen Spanisch.","es-g34-u06.s.4":"Ich wohne in Lima.","es-g34-u06.s.5":"Er schreibt einen Brief.","es-g34-u06.s.6":"Die Kinder rennen schnell.","es-g34-u06.s.7":"Wir öffnen das Fenster.","es-g34-u06.g.title":"Regelmäßige Verben auf -er / -ir im Präsens","es-g34-u06.g.x.0":"Verben auf -er: com-o, com-es, com-e, com-emos, com-en.","es-g34-u06.g.x.1":"Verben auf -ir: viv-o, viv-es, viv-e, viv-imos, viv-en. Nur „wir“ ist anders: -imos.","es-g34-u06.g.x.2":"Vergleich mit -ar: tú hablas / tú comes / tú vives. Merk dir: aus a wird e.","es-g34-u06.g.0":"Ich esse Brot.","es-g34-u06.g.1":"Du liest viel.","es-g34-u06.g.2":"Sie wohnt in Madrid.","es-g34-u06.g.3":"Wir wohnen hier.","es-g34-u06.g.4":"Sie trinken Wasser.","es-g34-u06.g.5":"Wir essen zusammen.","es-g34-u06.g.5.task":"Schreib den Satz als „Nosotros … juntos“","es-g34-u06.g.6":"Sie schreibt einen Brief.","es-g34-u06.g.6.task":"Ändere den Satz so, dass er mit „Ella“ beginnt","es-g34-u06.g.7":"Du öffnest die Tür.","es-g34-u06.g.7.task":"Ändere den Satz so, dass er mit „Tú“ beginnt","es-g34-u07.title":"Ich mag: gustar","es-g34-u07.tip":"Gusta/gustan richtet sich nicht nach „ich“, sondern nach dem, was man mag. Mehrere Dinge: gustan!","es-g34-u07.w.0":"Schokolade","es-g34-u07.w.1":"Fußball","es-g34-u07.w.2":"Film","es-g34-u07.w.3":"Sport","es-g34-u07.w.4":"Gemüse","es-g34-u07.w.5":"Nachtisch","es-g34-u07.w.6":"Hausaufgaben","es-g34-u07.w.7":"Lieblings-","es-g34-u07.w.8":"tanzen","es-g34-u07.w.9":"singen","es-g34-u07.s.0":"Ich mag Schokolade.","es-g34-u07.s.1":"Ich mag Sport.","es-g34-u07.s.2":"Magst du Fußball?","es-g34-u07.s.3":"Ich mag kein Gemüse.","es-g34-u07.s.4":"Mateo tanzt gern.","es-g34-u07.s.5":"Mein Lieblingsnachtisch ist Eis.","es-g34-u07.s.6":"Wir schauen gern Filme.","es-g34-u07.s.7":"Ich mag keine Hausaufgaben.","es-g34-u07.g.title":"Gustar: me gusta / me gustan","es-g34-u07.g.x.0":"„Ich mag“ heißt me gusta. Magst du eine Sache: gusta. Mehrere Sachen: gustan.","es-g34-u07.g.x.1":"Me gusta el helado. / Me gustan las fresas.","es-g34-u07.g.x.2":"Du: te gusta. Er/sie: le gusta. Wir: nos gusta. Mit einem Namen: A Ana le gusta…","es-g34-u07.g.x.3":"Bei einer Tätigkeit immer gusta: Me gusta bailar.","es-g34-u07.g.0":"Ich mag Schokolade.","es-g34-u07.g.1":"Ich mag Filme.","es-g34-u07.g.2":"Magst du Fußball?","es-g34-u07.g.3":"Lucía singt gern.","es-g34-u07.g.4":"Wir mögen Musik.","es-g34-u07.g.5":"Ich mag Sport.","es-g34-u07.g.5.task":"Ändere es zu „los deportes“ (Mehrzahl)","es-g34-u07.g.6":"Ich mag keine Hausaufgaben.","es-g34-u07.g.6.task":"Mach den Satz verneint (no)","es-g34-u07.g.7":"Magst du Gemüse?","es-g34-u07.g.7.task":"Mach daraus eine Frage mit „¿Te…?“","es-g34-u07.st.title":"Zeit für einen Snack","es-g34-u07.st.l.0":"Hugo, magst du Schokolade?","es-g34-u07.st.l.1":"Ja! Ich mag sie sehr. Und du?","es-g34-u07.st.l.2":"Ich mag Erdbeeren. Das ist mein Lieblingsnachtisch.","es-g34-u07.st.l.3":"Magst du Gemüse?","es-g34-u07.st.l.4":"Nein, das mag ich nicht. Aber Suppe mag ich.","es-g34-u07.st.l.5":"Meine Mama kocht gern Suppe. Komm, wir gehen zu mir nach Hause!","es-g34-u07.st.q.0":"Was ist Sofías Lieblingsnachtisch?","es-g34-u07.st.q.0.o.0":"Schokolade","es-g34-u07.st.q.0.o.1":"Erdbeeren","es-g34-u07.st.q.0.o.2":"Suppe","es-g34-u07.st.q.1":"Was mag Sofía nicht?","es-g34-u07.st.q.1.o.0":"Suppe","es-g34-u07.st.q.1.o.1":"Erdbeeren","es-g34-u07.st.q.1.o.2":"Gemüse","es-g34-u08.title":"Mein, dein: mi, tu, su","es-g34-u08.tip":"Tu (dein) hat keinen Akzent, tú (du) schon. „Tú tienes tu libro“ – du hast dein Buch.","es-g34-u08.w.0":"Spielzeug","es-g34-u08.w.1":"Fahrrad","es-g34-u08.w.2":"Haustier","es-g34-u08.w.3":"Nachbar","es-g34-u08.w.4":"Cousin","es-g34-u08.w.5":"Onkel","es-g34-u08.w.6":"Tante","es-g34-u08.w.7":"Zimmer","es-g34-u08.w.8":"Telefon","es-g34-u08.w.9":"Geld","es-g34-u08.s.0":"Mein Haustier ist ein Hund.","es-g34-u08.s.1":"Dein Fahrrad ist neu.","es-g34-u08.s.2":"Sein Zimmer ist groß.","es-g34-u08.s.3":"Unser Haus ist nah.","es-g34-u08.s.4":"Meine Cousins wohnen in Chile.","es-g34-u08.s.5":"Wo ist dein Telefon?","es-g34-u08.s.6":"Meine Tante hat zwei Katzen.","es-g34-u08.s.7":"Seine Spielsachen sind in der Kiste.","es-g34-u08.g.title":"Besitzwörter mi / tu / su / nuestro","es-g34-u08.g.x.0":"Mein = mi, dein = tu, sein/ihr = su, unser = nuestro/nuestra.","es-g34-u08.g.x.1":"Ist die Sache in der Mehrzahl, kommt ein -s dazu: mis libros, tus zapatos, sus gatos.","es-g34-u08.g.x.2":"Nur nuestro ändert das Geschlecht: nuestro perro, nuestra casa.","es-g34-u08.g.0":"Mein Haustier ist eine Katze.","es-g34-u08.g.1":"Deine Schuhe sind neu.","es-g34-u08.g.2":"Sein Cousin wohnt in Mexiko.","es-g34-u08.g.3":"Unser Haus ist schön.","es-g34-u08.g.4":"Unsere Nachbarn sind nett.","es-g34-u08.g.5":"Meine Spielsachen sind hier.","es-g34-u08.g.5.task":"Mach daraus die Mehrzahl","es-g34-u08.g.6":"Dein Telefon ist neu.","es-g34-u08.g.6.task":"Schreib den Satz mit „Tu“ (dein)","es-g34-u08.g.7":"Ihre Tante wohnt in der Nähe.","es-g34-u08.g.7.task":"Schreib den Satz mit „Su“ (ihre)","es-g34-u09.title":"Was? Wer? Wo?: Fragen stellen","es-g34-u09.tip":"Vor eine Frage kommt immer das umgedrehte Fragezeichen ¿. Beim Sprechen geht die Stimme am Ende nach oben.","es-g34-u09.w.0":"was","es-g34-u09.w.1":"wer","es-g34-u09.w.2":"wo","es-g34-u09.w.3":"wann","es-g34-u09.w.4":"wie","es-g34-u09.w.5":"wie viel","es-g34-u09.w.6":"warum","es-g34-u09.w.7":"Antwort","es-g34-u09.w.8":"Frage","es-g34-u09.w.9":"kosten","es-g34-u09.s.0":"Was ist das?","es-g34-u09.s.1":"Wer ist sie?","es-g34-u09.s.2":"Wo wohnst du?","es-g34-u09.s.3":"Wann ist die Party?","es-g34-u09.s.4":"Wie heißt du?","es-g34-u09.s.5":"Wie viel kostet das Buch?","es-g34-u09.s.6":"Warum weinst du?","es-g34-u09.s.7":"Ich habe eine Frage.","es-g34-u09.g.title":"Fragewörter: qué, quién, dónde, cuándo, cómo, cuánto","es-g34-u09.g.x.0":"Alle Fragewörter haben einen Akzent: qué (was), quién (wer), dónde (wo), cuándo (wann), cómo (wie), cuánto (wie viel).","es-g34-u09.g.x.1":"Eine Frage beginnt mit ¿ und endet mit ?: ¿Dónde está el gato?","es-g34-u09.g.x.2":"Das Verb steht meist direkt hinter dem Fragewort: ¿Qué comes? ¿Quién canta?","es-g34-u09.g.0":"Was isst du?","es-g34-u09.g.1":"Wer ist dein Freund?","es-g34-u09.g.2":"Wo ist mein Rucksack?","es-g34-u09.g.3":"Wann hast du Geburtstag?","es-g34-u09.g.4":"Wie geht es dir?","es-g34-u09.g.4.task":"Mach daraus eine Frage mit „¿Cómo…?“","es-g34-u09.g.5":"Wie viel kostet es?","es-g34-u09.g.6":"Wo wohnt Lucía?","es-g34-u09.g.6.task":"Mach daraus eine Frage mit „¿Dónde…?“","es-g34-u09.g.7":"Was liest Mateo?","es-g34-u09.g.7.task":"Mach daraus eine Frage mit „¿Qué…?“","es-g34-u10.title":"Nein, ich nicht: Verneinung","es-g34-u10.tip":"Im Spanischen darf man zweimal verneinen, wie in „No … nada“. Das ist richtig so – anders als im Englischen.","es-g34-u10.w.0":"nichts","es-g34-u10.w.1":"nie","es-g34-u10.w.2":"niemand","es-g34-u10.w.3":"immer","es-g34-u10.w.4":"auch","es-g34-u10.w.5":"auch nicht","es-g34-u10.w.6":"noch","es-g34-u10.w.7":"schon","es-g34-u10.w.8":"Lüge","es-g34-u10.w.9":"Wahrheit","es-g34-u10.s.0":"Ich habe keinen Hunger.","es-g34-u10.s.1":"Ich mag die Kälte nicht.","es-g34-u10.s.2":"Ich will nichts.","es-g34-u10.s.3":"Ich komme nie zu spät.","es-g34-u10.s.4":"Hier ist niemand.","es-g34-u10.s.5":"Ich gehe auch nicht.","es-g34-u10.s.6":"Ich kann noch nicht lesen.","es-g34-u10.s.7":"Das ist nicht wahr.","es-g34-u10.g.title":"Verneinung: no + Verb, nada, nunca, nadie","es-g34-u10.g.x.0":"Für „nicht“ setzt du no vor das Verb: No como. No tengo gato.","es-g34-u10.g.x.1":"Steht nada (nichts), nadie (niemand) oder nunca (nie) hinter dem Verb, bleibt das no trotzdem: No veo nada.","es-g34-u10.g.x.2":"„Ich auch“ heißt también, „ich auch nicht“ heißt tampoco.","es-g34-u10.g.0":"Ich habe keinen Hunger.","es-g34-u10.g.1":"Ich sehe nichts.","es-g34-u10.g.2":"Zu Hause ist niemand.","es-g34-u10.g.3":"Ich esse nie Süßigkeiten.","es-g34-u10.g.4":"Ich will auch nicht.","es-g34-u10.g.5":"Ich mag keinen Regen.","es-g34-u10.g.5.task":"Mach den Satz verneint (no)","es-g34-u10.g.6":"Sie isst kein Fleisch.","es-g34-u10.g.6.task":"Mach den Satz verneint (no)","es-g34-u10.g.7":"Ich will nichts.","es-g34-u10.g.7.task":"Verneine den Satz mit „nada“","es-g34-u11.title":"Es gibt: hay","es-g34-u11.tip":"Hay heißt „es gibt“, está heißt „ist (irgendwo)“. Hay un gato (Es gibt eine Katze) / El gato está aquí (Die Katze ist hier).","es-g34-u11.w.0":"Markt","es-g34-u11.w.1":"Laden","es-g34-u11.w.2":"Brot","es-g34-u11.w.3":"Eier","es-g34-u11.w.4":"Obst","es-g34-u11.w.5":"Milch","es-g34-u11.w.6":"Tüte (Tasche)","es-g34-u11.w.7":"Kühlschrank","es-g34-u11.w.8":"viel","es-g34-u11.w.9":"wenig","es-g34-u11.s.0":"Im Garten ist eine Katze.","es-g34-u11.s.1":"Auf dem Markt gibt es viel Obst.","es-g34-u11.s.2":"Im Kühlschrank ist keine Milch.","es-g34-u11.s.3":"Gibt es Brot?","es-g34-u11.s.4":"In der Tüte sind sechs Eier.","es-g34-u11.s.5":"Es gibt nur wenig Wasser.","es-g34-u11.s.6":"In meiner Klasse sind zwanzig Kinder.","es-g34-u11.s.7":"In der Nähe gibt es einen Laden.","es-g34-u11.g.title":"Hay: es gibt / es gibt nicht","es-g34-u11.g.x.0":"„Es gibt“ sagt man einfach mit hay – egal ob eins oder viele: Hay un gato. Hay tres gatos.","es-g34-u11.g.x.1":"Wenn es etwas nicht gibt: No hay leche.","es-g34-u11.g.x.2":"Bei Mengen passt du mucho/mucha (viel) und poco/poca (wenig) an das Nomen an: mucha fruta, pocos huevos.","es-g34-u11.g.0":"Auf der Straße ist ein Hund.","es-g34-u11.g.1":"Hier gibt es viele Läden.","es-g34-u11.g.2":"Es gibt kein Brot.","es-g34-u11.g.3":"Es gibt viel Obst.","es-g34-u11.g.4":"Es gibt nur wenige Eier.","es-g34-u11.g.5":"Zu Hause ist keine Milch.","es-g34-u11.g.5.task":"Mach den Satz verneint (no)","es-g34-u11.g.6":"Gibt es hier einen Kühlschrank?","es-g34-u11.g.6.task":"Mach daraus eine Frage","es-g34-u11.g.7":"Im Park sind viele Kinder.","es-g34-u11.g.7.task":"Schreib den Satz mit „muchos“ (viele)","es-g34-u12.title":"Hungrig, durstig: Ausdrücke mit tener","es-g34-u12.tip":"Nach dem Alter fragt man mit „¿Cuántos años tienes?“ (Wie alt bist du?). Die Antwort: „Tengo … años.“","es-g34-u12.w.0":"Hunger","es-g34-u12.w.1":"Durst","es-g34-u12.w.2":"Müdigkeit","es-g34-u12.w.3":"Angst","es-g34-u12.w.4":"Eile","es-g34-u12.w.5":"Glück","es-g34-u12.w.6":"Recht (Grund)","es-g34-u12.w.7":"Jahre (Alter)","es-g34-u12.w.8":"Sandwich","es-g34-u12.w.9":"Decke","es-g34-u12.s.0":"Ich habe Hunger.","es-g34-u12.s.1":"Hast du Durst?","es-g34-u12.s.2":"Ich bin neun Jahre alt.","es-g34-u12.s.3":"Meine kleine Schwester ist müde.","es-g34-u12.s.4":"Wir haben es eilig.","es-g34-u12.s.5":"Ich habe keine Angst.","es-g34-u12.s.6":"Du hast recht.","es-g34-u12.s.7":"Mir ist kalt, ich brauche eine Decke.","es-g34-u12.g.title":"Ausdrücke mit tener: tengo hambre, tengo años","es-g34-u12.g.x.0":"Tener heißt „haben“ – und im Spanischen „hat“ man Hunger, Durst und sein Alter: Tengo hambre. Tengo diez años.","es-g34-u12.g.x.1":"Tengo, tienes, tiene, tenemos, tienen. Nur yo ist besonders: tengo.","es-g34-u12.g.x.2":"Tener frío (frieren), tener calor (schwitzen), tener sueño (müde sein), tener miedo (Angst haben), tener prisa (es eilig haben), tener razón (recht haben).","es-g34-u12.g.0":"Ich habe Hunger.","es-g34-u12.g.1":"Hast du Durst?","es-g34-u12.g.2":"Sie ist acht Jahre alt.","es-g34-u12.g.3":"Wir haben es eilig.","es-g34-u12.g.4":"Sie haben Angst.","es-g34-u12.g.5":"Mein Opa ist siebzig Jahre alt.","es-g34-u12.g.5.task":"Schreib den Satz als „Mi abuelo … setenta“","es-g34-u12.g.6":"Ich bin nicht müde.","es-g34-u12.g.6.task":"Mach den Satz verneint (no)","es-g34-u12.g.7":"Ist dir kalt?","es-g34-u12.g.7.task":"Mach daraus eine Frage mit „¿Tú…?“","es-g34-u12.st.title":"Große Pause","es-g34-u12.st.l.0":"Ich habe so einen Hunger. Hast du ein Sandwich?","es-g34-u12.st.l.1":"Ja, ich habe zwei. Nimm eins.","es-g34-u12.st.l.2":"Danke! Ich habe auch Durst.","es-g34-u12.st.l.3":"Am Brunnen gibt es Wasser. Wie alt bist du, Pablo?","es-g34-u12.st.l.4":"Neun. Und du?","es-g34-u12.st.l.5":"Ich bin zehn. Beeil dich, der Unterricht fängt gleich an!","es-g34-u12.st.q.0":"Was möchte Pablo?","es-g34-u12.st.q.0.o.0":"Ein Buch","es-g34-u12.st.q.0.o.1":"Ein Sandwich und Wasser","es-g34-u12.st.q.0.o.2":"Einen Ball","es-g34-u12.st.q.1":"Wie alt ist Marta?","es-g34-u12.st.q.1.o.0":"Neun Jahre","es-g34-u12.st.q.1.o.1":"Zehn Jahre","es-g34-u12.st.q.1.o.2":"Acht Jahre","es-g34-u13.title":"Ser oder estar?","es-g34-u13.tip":"Wenn du unsicher bist, frag dich: „Ist es immer so?“ → ser. „Ist es gerade so? Wo ist es?“ → estar.","es-g34-u13.w.0":"langweilig","es-g34-u13.w.1":"lustig","es-g34-u13.w.2":"krank","es-g34-u13.w.3":"gesund","es-g34-u13.w.4":"offen","es-g34-u13.w.5":"geschlossen","es-g34-u13.w.6":"heiß","es-g34-u13.w.7":"kalt","es-g34-u13.w.8":"jung","es-g34-u13.w.9":"freundlich","es-g34-u13.s.0":"Meine Lehrerin ist jung und freundlich.","es-g34-u13.s.1":"Ich bin heute krank.","es-g34-u13.s.2":"Die Suppe ist heiß.","es-g34-u13.s.3":"Das Spiel ist lustig.","es-g34-u13.s.4":"Der Laden ist geschlossen.","es-g34-u13.s.5":"Lucía kommt aus Peru.","es-g34-u13.s.6":"Wir sind in der Schule.","es-g34-u13.s.7":"Das Eis ist kalt.","es-g34-u13.g.title":"Ser und estar unterscheiden","es-g34-u13.g.x.0":"Ser = so ist es immer (Name, Beruf, Land, Charakter, Uhrzeit): Soy alto. Es profesora. Son las dos.","es-g34-u13.g.x.1":"Estar = Zustand, Ort oder Gefühl gerade jetzt: Estoy enfermo. Está en casa. Están contentos.","es-g34-u13.g.x.2":"Dasselbe Wort kann etwas anderes bedeuten: Es aburrido (ein langweiliger Mensch) / Está aburrido (langweilt sich gerade).","es-g34-u13.g.0":"Mein Papa ist Arzt.","es-g34-u13.g.1":"Heute bin ich müde.","es-g34-u13.g.2":"Die Tür ist offen.","es-g34-u13.g.3":"Wir kommen aus Mexiko.","es-g34-u13.g.4":"Der Kaffee ist heiß.","es-g34-u13.g.5":"Sie ist krank.","es-g34-u13.g.5.task":"Schreib den Satz mit „enferma“ (krank)","es-g34-u13.g.6":"Der Laden ist geschlossen.","es-g34-u13.g.6.task":"Schreib den Satz mit „cerrada“ (geschlossen)","es-g34-u13.g.7":"Meine Freunde sind lustig.","es-g34-u13.g.7.task":"Mach daraus die Mehrzahl","es-g34-u14.title":"Wohin gehst du? ir + a","es-g34-u14.tip":"„¿Adónde vas?“ heißt „Wohin gehst du?“. Die Antwort beginnt mit Voy a…","es-g34-u14.w.0":"gehen","es-g34-u14.w.1":"Kino","es-g34-u14.w.2":"Strand","es-g34-u14.w.3":"Supermarkt","es-g34-u14.w.4":"Museum","es-g34-u14.w.5":"Bahnhof","es-g34-u14.w.6":"Berg","es-g34-u14.w.7":"Restaurant","es-g34-u14.w.8":"Zoo","es-g34-u14.w.9":"Wochenende","es-g34-u14.s.0":"Ich gehe zum Strand.","es-g34-u14.s.1":"Wohin gehst du?","es-g34-u14.s.2":"Wir gehen ins Kino.","es-g34-u14.s.3":"Mama geht zum Supermarkt.","es-g34-u14.s.4":"Meine Freunde gehen in den Zoo.","es-g34-u14.s.5":"Am Wochenende fahren wir in die Berge.","es-g34-u14.s.6":"Ich fahre mit dem Fahrrad zum Bahnhof.","es-g34-u14.s.7":"Gehst du heute ins Museum?","es-g34-u14.g.title":"Das Verb ir mit a / al","es-g34-u14.g.x.0":"„Gehen“ heißt ir: voy, vas, va, vamos, van. Es ändert sich stark, also lern es auswendig.","es-g34-u14.g.x.1":"Wohin man geht, sagt man mit a: Voy a la playa.","es-g34-u14.g.x.2":"A + el wird zu al: Voy al cine. (nicht: a el cine)","es-g34-u14.g.0":"Ich gehe zur Schule.","es-g34-u14.g.1":"Gehst du in den Park?","es-g34-u14.g.2":"Sie geht zum Supermarkt.","es-g34-u14.g.2.task":"Ändere den Satz so, dass er mit „Ella“ beginnt","es-g34-u14.g.3":"Wir gehen ins Kino.","es-g34-u14.g.4":"Ich gehe ins Museum.","es-g34-u14.g.5":"Ich gehe zum Strand.","es-g34-u14.g.6":"Wir gehen in den Zoo.","es-g34-u14.g.6.task":"Ändere den Satz so, dass er mit „Nosotros“ beginnt","es-g34-u14.g.7":"Sie fahren in die Berge.","es-g34-u14.g.7.task":"Ändere den Satz so, dass er mit „Ellos“ beginnt","es-g34-u14.st.title":"Pläne fürs Wochenende","es-g34-u14.st.l.0":"Elena, wohin gehst du am Samstag?","es-g34-u14.st.l.1":"Ich gehe mit meiner Familie in den Zoo. Und du?","es-g34-u14.st.l.2":"Ich gehe zum Strand. Es ist heiß.","es-g34-u14.st.l.3":"Schön! Am Sonntag gehen wir ins Kino. Kommst du mit?","es-g34-u14.st.l.4":"Ja, ich komme mit. Um wie viel Uhr?","es-g34-u14.st.l.5":"Um fünf. Bis Sonntag!","es-g34-u14.st.q.0":"Wohin geht Carlos am Samstag?","es-g34-u14.st.q.0.o.0":"In den Zoo","es-g34-u14.st.q.0.o.1":"Zum Strand","es-g34-u14.st.q.0.o.2":"Ins Kino","es-g34-u14.st.q.1":"Um wie viel Uhr ist der Film am Sonntag?","es-g34-u14.st.q.1.o.0":"Um drei","es-g34-u14.st.q.1.o.1":"Um vier","es-g34-u14.st.q.1.o.2":"Um fünf","es-g34-u15.title":"Wie spät ist es?","es-g34-u15.tip":"Schau auf die Uhr und sag Son las… Vergiss nicht: Nur bei ein Uhr heißt es Es la una!","es-g34-u15.w.0":"Uhrzeit (Stunde)","es-g34-u15.w.1":"Uhr","es-g34-u15.w.2":"Minute","es-g34-u15.w.3":"Mittag","es-g34-u15.w.4":"Mitternacht","es-g34-u15.w.5":"früh","es-g34-u15.w.6":"spät","es-g34-u15.w.7":"Frühstück","es-g34-u15.w.8":"Abendessen","es-g34-u15.w.9":"Pause","es-g34-u15.s.0":"Wie spät ist es?","es-g34-u15.s.1":"Es ist ein Uhr.","es-g34-u15.s.2":"Es ist drei Uhr.","es-g34-u15.s.3":"Es ist halb sechs.","es-g34-u15.s.4":"Es ist Viertel nach acht.","es-g34-u15.s.5":"Das Frühstück ist um sieben.","es-g34-u15.s.6":"Die Pause ist um elf.","es-g34-u15.s.7":"Ich stehe früh auf.","es-g34-u15.g.title":"Uhrzeit sagen: Es la una / Son las dos","es-g34-u15.g.x.0":"Nur bei ein Uhr sagt man Es la una. Ab zwei heißt es Son las dos, Son las tres…","es-g34-u15.g.x.1":"Minuten hängst du mit y an: Son las dos y diez (2:10). Halb ist y media, Viertel nach ist y cuarto.","es-g34-u15.g.x.2":"„Um … Uhr“ heißt a las: La clase es a las nueve.","es-g34-u15.g.0":"Es ist ein Uhr.","es-g34-u15.g.1":"Es ist vier Uhr.","es-g34-u15.g.2":"Es ist halb sieben.","es-g34-u15.g.3":"Es ist Viertel nach neun.","es-g34-u15.g.4":"Das Abendessen ist um acht.","es-g34-u15.g.5":"Es ist zehn Uhr.","es-g34-u15.g.5.task":"Ändere die Uhrzeit auf eine Stunde später","es-g34-u15.g.6":"Die Pause ist um elf.","es-g34-u15.g.6.task":"Schreib den Satz mit „once“ (elf)","es-g34-u15.g.7":"Es ist halb zwei.","es-g34-u15.g.7.task":"Füge „y media“ (halb) hinzu","es-g34-u16.title":"Dies, das: este, ese, aquel","es-g34-u16.tip":"Zeig mit der Hand: In deiner Hand ist este, bei deinem Freund ist ese, ganz weit weg ist aquel!","es-g34-u16.w.0":"dieser (hier)","es-g34-u16.w.1":"der (da)","es-g34-u16.w.2":"jener (dort drüben)","es-g34-u16.w.3":"Hemd","es-g34-u16.w.4":"Rock","es-g34-u16.w.5":"Kappe","es-g34-u16.w.6":"Preis","es-g34-u16.w.7":"billig","es-g34-u16.w.8":"teuer","es-g34-u16.w.9":"Größe","es-g34-u16.s.0":"Dieses Buch gehört mir.","es-g34-u16.s.1":"Das Hemd da ist schön.","es-g34-u16.s.2":"Der Berg dort drüben ist hoch.","es-g34-u16.s.3":"Wie viel kostet diese Kappe?","es-g34-u16.s.4":"Die Uhr da ist sehr teuer.","es-g34-u16.s.5":"Diese Schuhe sind billig.","es-g34-u16.s.6":"Ich möchte den blauen Rock da.","es-g34-u16.s.7":"Welche Größe ist das?","es-g34-u16.g.title":"Hinweiswörter: este (dieser), ese (der da), aquel (jener dort)","es-g34-u16.g.x.0":"Nah bei dir: este. Ein bisschen weiter weg: ese. Ganz weit weg: aquel.","es-g34-u16.g.x.1":"Sie passen sich dem Nomen an: este libro / esta casa / estos libros / estas casas.","es-g34-u16.g.x.2":"Ese → esa, esos, esas / aquel → aquella, aquellos, aquellas.","es-g34-u16.g.0":"Dieses Buch ist neu.","es-g34-u16.g.1":"Dieses Hemd ist weiß.","es-g34-u16.g.2":"Der Hund da ist groß.","es-g34-u16.g.3":"Das Haus dort drüben ist alt.","es-g34-u16.g.4":"Diese Schuhe sind teuer.","es-g34-u16.g.5":"Die Kappen da sind billig.","es-g34-u16.g.5.task":"Mach daraus die Mehrzahl","es-g34-u16.g.6":"Der Rock da ist schön.","es-g34-u16.g.6.task":"Schreib den Satz mit „esa“ (die da)","es-g34-u16.g.7":"Der Baum dort drüben ist hoch.","es-g34-u16.g.7.task":"Schreib den Satz mit „aquel“ (jener dort)","es-g34-u17.title":"Ich will, ich kann: querer, poder","es-g34-u17.tip":"Mit „¿Puedo…?“ bittest du um Erlaubnis: ¿Puedo entrar? ¿Puedo salir?","es-g34-u17.w.0":"wollen","es-g34-u17.w.1":"können","es-g34-u17.w.2":"spielen","es-g34-u17.w.3":"schlafen","es-g34-u17.w.4":"helfen","es-g34-u17.w.5":"hinausgehen","es-g34-u17.w.6":"hineingehen","es-g34-u17.w.7":"anmalen","es-g34-u17.w.8":"fliegen","es-g34-u17.w.9":"Erlaubnis","es-g34-u17.s.0":"Ich will mit dir spielen.","es-g34-u17.s.1":"Willst du ein Eis?","es-g34-u17.s.2":"Heute kann ich nicht raus.","es-g34-u17.s.3":"Darf ich reinkommen?","es-g34-u17.s.4":"Vögel können fliegen.","es-g34-u17.s.5":"Wir wollen die Wand anmalen.","es-g34-u17.s.6":"Mein Bruder will schlafen.","es-g34-u17.s.7":"Kannst du Mama helfen?","es-g34-u17.g.title":"Querer (wollen) und poder (können) + Grundform","es-g34-u17.g.x.0":"Querer: quiero, quieres, quiere, queremos, quieren. Aus e wird ie (außer bei nosotros).","es-g34-u17.g.x.1":"Poder: puedo, puedes, puede, podemos, pueden. Aus o wird ue (außer bei nosotros).","es-g34-u17.g.x.2":"Dahinter kommt die Grundform des Verbs: Quiero comer. Puedo nadar.","es-g34-u17.g.0":"Ich will spielen.","es-g34-u17.g.1":"Willst du ein Eis?","es-g34-u17.g.2":"Sie kann schwimmen.","es-g34-u17.g.3":"Wir können helfen.","es-g34-u17.g.4":"Sie wollen rausgehen.","es-g34-u17.g.5":"Heute kann ich nicht raus.","es-g34-u17.g.5.task":"Mach den Satz verneint (no)","es-g34-u17.g.6":"Kannst du mit mir malen?","es-g34-u17.g.6.task":"Mach daraus eine Frage mit „¿Tú…?“","es-g34-u17.g.7":"Wir wollen schlafen.","es-g34-u17.g.7.task":"Ändere den Satz so, dass er mit „Nosotros“ beginnt","es-g34-u17.st.title":"Darf ich draußen spielen?","es-g34-u17.st.l.0":"Mama, darf ich draußen spielen?","es-g34-u17.st.l.1":"Du willst jetzt spielen? Erst die Hausaufgaben.","es-g34-u17.st.l.2":"Ich habe keine Hausaufgaben mehr. Ich kann in der Küche helfen!","es-g34-u17.st.l.3":"Sehr gut. Du darfst eine Stunde raus.","es-g34-u17.st.l.4":"Danke! Ich will mit Diego Fußball spielen.","es-g34-u17.st.q.0":"Was soll Hugo laut Mama zuerst machen?","es-g34-u17.st.q.0.o.0":"Hausaufgaben","es-g34-u17.st.q.0.o.1":"Abendessen","es-g34-u17.st.q.0.o.2":"Mittagsschlaf","es-g34-u17.st.q.1":"Wie lange darf Hugo draußen spielen?","es-g34-u17.st.q.1.o.0":"Dreißig Minuten","es-g34-u17.st.q.1.o.1":"Eine Stunde","es-g34-u17.st.q.1.o.2":"Zwei Stunden","es-g34-u18.title":"Monate, Jahreszeiten und Datum","es-g34-u18.tip":"Anders als im Englischen steht die Zahl zuerst: „5 de mayo“. Sag deinen Geburtstag auf Spanisch!","es-g34-u18.w.0":"Januar","es-g34-u18.w.1":"April","es-g34-u18.w.2":"Juli","es-g34-u18.w.3":"Oktober","es-g34-u18.w.4":"Dezember","es-g34-u18.w.5":"Frühling","es-g34-u18.w.6":"Sommer","es-g34-u18.w.7":"Herbst","es-g34-u18.w.8":"Winter","es-g34-u18.w.9":"Ferien","es-g34-u18.s.0":"Heute ist der 3. Mai.","es-g34-u18.s.1":"Mein Geburtstag ist im Juli.","es-g34-u18.s.2":"Im Winter ist es kalt.","es-g34-u18.s.3":"Der Frühling ist wunderschön.","es-g34-u18.s.4":"Der Wievielte ist heute?","es-g34-u18.s.5":"Die Ferien sind im Sommer.","es-g34-u18.s.6":"Im Herbst fallen die Blätter.","es-g34-u18.s.7":"Dezember ist der letzte Monat.","es-g34-u18.g.title":"Das Datum sagen: el + Zahl + de + Monat","es-g34-u18.g.x.0":"Beim Datum kommt zuerst die Zahl, dann der Monat: Hoy es cinco de abril. (5. April)","es-g34-u18.g.x.1":"Nur der Erste heißt el primero: el primero de enero.","es-g34-u18.g.x.2":"Monate und Jahreszeiten schreibt man klein. „Im“ Monat oder in der Jahreszeit heißt en: en julio, en verano.","es-g34-u18.g.0":"Heute ist der 2. März.","es-g34-u18.g.1":"Mein Geburtstag ist am 10. Juli.","es-g34-u18.g.2":"Heute ist der 1. Januar.","es-g34-u18.g.3":"Im Sommer ist es heiß.","es-g34-u18.g.4":"Die Schule beginnt im September.","es-g34-u18.g.5":"Heute ist der 5. April.","es-g34-u18.g.5.task":"Ändere das Datum auf den nächsten Tag","es-g34-u18.g.6":"Im Winter schneit es.","es-g34-u18.g.6.task":"Schreib den Satz als „invierno … nieva“","es-g34-u18.g.7":"Mein Geburtstag ist im Dezember.","es-g34-u18.g.7.task":"Schreib den Satz mit „diciembre“","es-g34-u19.title":"Immer, manchmal: mein Tag","es-g34-u19.tip":"Erzähl deinen Tag auf Spanisch: Siempre…, normalmente…, a veces…, nunca….","es-g34-u19.w.0":"manchmal","es-g34-u19.w.1":"normalerweise","es-g34-u19.w.2":"frühstücken","es-g34-u19.w.3":"zu Mittag essen","es-g34-u19.w.4":"zu Abend essen","es-g34-u19.w.5":"sich ausruhen","es-g34-u19.w.6":"ankommen","es-g34-u19.w.7":"schauen","es-g34-u19.w.8":"Fernseher","es-g34-u19.w.9":"Tagesablauf","es-g34-u19.s.0":"Ich frühstücke immer um sieben.","es-g34-u19.s.1":"Manchmal esse ich in der Schule zu Mittag.","es-g34-u19.s.2":"Normalerweise komme ich um vier nach Hause.","es-g34-u19.s.3":"Am Nachmittag ruhe ich mich ein bisschen aus.","es-g34-u19.s.4":"Morgens schaue ich nie fern.","es-g34-u19.s.5":"Wir essen um acht zu Abend.","es-g34-u19.s.6":"Samstags spiele ich mit meinen Cousins.","es-g34-u19.s.7":"Mein Tagesablauf ist einfach.","es-g34-u19.g.title":"Häufigkeitswörter: siempre, normalmente, a veces, nunca","es-g34-u19.g.x.0":"Wie oft man etwas tut: siempre (immer) > normalmente (normalerweise) > a veces (manchmal) > nunca (nie).","es-g34-u19.g.x.1":"Sie stehen meist am Satzanfang oder vor dem Verb: Siempre desayuno. A veces como pizza.","es-g34-u19.g.x.2":"„Jeden …“ bei Wochentagen heißt los + Tag: los lunes, los sábados. „Morgens“ heißt por la mañana, „nachmittags“ por la tarde.","es-g34-u19.g.0":"Ich frühstücke immer mit meiner Familie.","es-g34-u19.g.1":"Manchmal esse ich in der Schule.","es-g34-u19.g.2":"Ich komme nie zu spät.","es-g34-u19.g.2.task":"Schreib den Satz mit „nunca“ (nie)","es-g34-u19.g.3":"Normalerweise esse ich um acht zu Abend.","es-g34-u19.g.4":"Montags habe ich Musikunterricht.","es-g34-u19.g.5":"Morgens frühstücke ich.","es-g34-u19.g.6":"Ich schaue nie fern.","es-g34-u19.g.6.task":"Schreib den Satz mit „nunca“ (nie)","es-g34-u19.g.7":"Samstags ruhe ich mich aus.","es-g34-u19.g.7.task":"Ändere es zu „jeden Samstag“ (los sábados)","es-g34-u20.title":"Und, aber, weil","es-g34-u20.tip":"Bau mit pero und porque längere Sätze: „Quiero…, pero…“ / „… porque …“","es-g34-u20.w.0":"aber","es-g34-u20.w.1":"weil","es-g34-u20.w.2":"auch","es-g34-u20.w.3":"also (dann)","es-g34-u20.w.4":"zufrieden (froh)","es-g34-u20.w.5":"müde","es-g34-u20.w.6":"schwierig","es-g34-u20.w.7":"leicht","es-g34-u20.w.8":"Regen","es-g34-u20.w.9":"Spaziergang","es-g34-u20.s.0":"Ich habe einen Hund und eine Katze.","es-g34-u20.s.1":"Ich will raus, aber es regnet.","es-g34-u20.s.2":"Ich gehe nicht, weil ich müde bin.","es-g34-u20.s.3":"Die Hausaufgaben sind schwierig, aber ich schaffe sie.","es-g34-u20.s.4":"Ich bin froh, weil Freitag ist.","es-g34-u20.s.5":"Es regnet, also gibt es keinen Spaziergang.","es-g34-u20.s.6":"Ich lese gern und zeichne auch gern.","es-g34-u20.s.7":"Der Test ist leicht und kurz.","es-g34-u20.g.title":"Bindewörter y / pero / porque","es-g34-u20.g.x.0":"Y (und) verbindet zwei Dinge: pan y leche. Beginnt das nächste Wort mit i-, wird daraus e: padres e hijos.","es-g34-u20.g.x.1":"Pero (aber) verbindet Gegensätze: Es pequeño, pero fuerte.","es-g34-u20.g.x.2":"Porque (weil) nennt einen Grund: No salgo porque llueve. Es wird zusammengeschrieben – anders als die Frage ¿por qué?","es-g34-u20.g.0":"Ich habe Brot und Käse.","es-g34-u20.g.1":"Er ist klein, aber stark.","es-g34-u20.g.2":"Ich gehe nicht raus, weil es regnet.","es-g34-u20.g.3":"Eltern und Kinder spielen zusammen.","es-g34-u20.g.4":"Ich bin müde, also ruhe ich mich aus.","es-g34-u20.g.5":"Ich will spielen, aber ich habe Hausaufgaben.","es-g34-u20.g.5.task":"Verbinde die Sätze mit „pero“ zu einem Satz","es-g34-u20.g.6":"Ich bin glücklich, weil Samstag ist.","es-g34-u20.g.6.task":"Verbinde die Sätze mit „porque“ zu einem Satz","es-g34-u20.g.7":"Ich lese und zeichne gern.","es-g34-u20.g.7.task":"Verbinde die Sätze mit „y“ zu einem Satz"},u={"es-g56-u01.title":"Ich mache, ich gehe raus: unregelmäßige Verben","es-g56-u01.tip":"Bei „ich“ enden sie auf -go: hago, salgo, pongo, traigo, vengo, digo. Lern die sechs wie ein Lied.","es-g56-u01.w.0":"machen (tun)","es-g56-u01.w.1":"hinausgehen","es-g56-u01.w.2":"hinlegen (stellen)","es-g56-u01.w.3":"mitbringen","es-g56-u01.w.4":"kommen","es-g56-u01.w.5":"sagen","es-g56-u01.w.6":"kennen (Leute, Orte)","es-g56-u01.w.7":"Hausaufgaben","es-g56-u01.w.8":"Rucksack","es-g56-u01.w.9":"Schulhof","es-g56-u01.w.10":"Nachmittagssnack","es-g56-u01.w.11":"früh","es-g56-u01.s.0":"Ich mache nachmittags meine Hausaufgaben.","es-g56-u01.s.1":"Ich gehe um acht aus dem Haus.","es-g56-u01.s.2":"Ich lege meinen Rucksack auf den Stuhl.","es-g56-u01.s.3":"Ich bringe meinen Snack mit auf den Schulhof.","es-g56-u01.s.4":"Kommst du heute zu mir nach Hause?","es-g56-u01.s.5":"Ich sage immer die Wahrheit.","es-g56-u01.s.6":"Ich kenne alle meine Nachbarn.","es-g56-u01.s.7":"Meine Schwester macht früh ihr Bett.","es-g56-u01.g.title":"Verben mit -go bei yo: hago, salgo, pongo","es-g56-u01.g.x.0":"Hacer, salir, poner, traer, venir und decir enden nur bei „ich“ (yo) auf -go: hago, salgo, pongo, traigo, vengo, digo.","es-g56-u01.g.x.1":"Bei den anderen Personen sind sie fast regelmäßig: haces, hace, hacemos, hacen / sales, sale, salimos, salen.","es-g56-u01.g.x.2":"Venir und decir ändern sich auch bei tú und él: vienes, viene / dices, dice. Conocer wird zu conozco.","es-g56-u01.g.0":"Ich mache zu Hause meine Hausaufgaben.","es-g56-u01.g.1":"Ich gehe um drei raus.","es-g56-u01.g.2":"Ich decke den Tisch.","es-g56-u01.g.3":"Ich bringe das Brot mit.","es-g56-u01.g.4":"Du kommst mit mir.","es-g56-u01.g.5":"Ich komme aus der Schule.","es-g56-u01.g.5.task":"Ändere den Satz so, dass er mit „Yo“ beginnt","es-g56-u01.g.6":"Ich sage die Wahrheit.","es-g56-u01.g.6.task":"Ändere den Satz so, dass er mit „Yo“ beginnt","es-g56-u01.g.7":"Wir machen Sport.","es-g56-u01.g.7.task":"Ändere den Satz so, dass er mit „Nosotros“ beginnt","es-g56-u01.r.ko":"Ein Tag mit Mateo","es-g56-u01.r.genre":"Alltagsgeschichte","es-g56-u01.r.p.0":"Ich heiße Mateo und bin elf Jahre alt. Ich gehe um Viertel vor acht aus dem Haus. Ich packe meine Bücher und meinen Snack in den Rucksack und verabschiede mich von meiner Oma. Die Schule ist nah, deshalb komme ich mit dem Fahrrad.","es-g56-u01.r.p.1":"In der Pause gehe ich mit Lucía auf den Schulhof. Sie bringt immer Obst mit und ich bringe Kekse mit. Nach dem Unterricht mache ich meine Hausaufgaben in der Bibliothek. Ich kenne alle Lehrer, und sie kennen mich.","es-g56-u01.r.p.2":"Abends decke ich den Tisch und esse mit meiner Familie zu Abend. Mein Papa sagt, ich sei sehr verantwortungsvoll. Morgen mache ich alles genauso!","es-g56-u01.r.q.3.o.0":"Snack","es-g56-u01.r.q.3.o.1":"Hausaufgaben","es-g56-u01.r.q.3.o.2":"Fahrrad","es-g56-u01.r.q.3.o.3":"Bibliothek","es-g56-u02.title":"E→ie, o→ue: Verben, die ihre Form ändern","es-g56-u02.tip":"Nur nosotros ändert sich nicht! „Empezamos, volvemos“ behalten den ursprünglichen Vokal.","es-g56-u02.w.0":"anfangen","es-g56-u02.w.1":"denken","es-g56-u02.w.2":"verstehen","es-g56-u02.w.3":"lieber mögen","es-g56-u02.w.4":"zurückkommen","es-g56-u02.w.5":"zählen (erzählen)","es-g56-u02.w.6":"sich erinnern","es-g56-u02.w.7":"finden","es-g56-u02.w.8":"Mittagessen","es-g56-u02.w.9":"Schlüssel","es-g56-u02.w.10":"Hosentasche","es-g56-u02.w.11":"Unterrichtsstunde","es-g56-u02.s.0":"Der Unterricht fängt um neun an.","es-g56-u02.s.1":"Ich denke an meine Großeltern.","es-g56-u02.s.2":"Ich verstehe dieses Wort nicht.","es-g56-u02.s.3":"Ich esse lieber zu Hause zu Mittag.","es-g56-u02.s.4":"Ich komme um fünf nach Hause zurück.","es-g56-u02.s.5":"Ich zähle die Münzen in meiner Hosentasche.","es-g56-u02.s.6":"Erinnerst du dich an die Stunde von gestern?","es-g56-u02.s.7":"Ich finde meinen Schlüssel nicht.","es-g56-u02.g.title":"Verben mit Vokalwechsel: e→ie, o→ue","es-g56-u02.g.x.0":"Bei manchen Verben ändert sich der Vokal in der Mitte. E→ie: empiezo, piensas, entiende, prefieren.","es-g56-u02.g.x.1":"O→ue: vuelvo, cuentas, recuerda, encuentran.","es-g56-u02.g.x.2":"Nosotros ändert sich nicht: empezamos, volvemos. Stell dir einen Stiefel vor – nur nosotros steht außerhalb.","es-g56-u02.g.0":"Der Film fängt jetzt an.","es-g56-u02.g.1":"Ich denke an dich.","es-g56-u02.g.2":"Verstehst du die Stunde?","es-g56-u02.g.3":"Wir kommen spät zurück.","es-g56-u02.g.4":"Sie zählt bis zehn.","es-g56-u02.g.5":"Ich mag lieber Tee.","es-g56-u02.g.5.task":"Ändere den Satz so, dass er mit „Yo“ beginnt","es-g56-u02.g.6":"Sie kehren nach Hause zurück.","es-g56-u02.g.6.task":"Ändere den Satz so, dass er mit „Ellos“ beginnt","es-g56-u02.g.7":"Ich erinnere mich nicht an seinen Namen.","es-g56-u02.g.7.task":"Mach den Satz verneint (no)","es-g56-u03.title":"Aufstehen und waschen: reflexive Verben","es-g56-u03.tip":"Sag deinen Morgen der Reihe nach: Me despierto, me levanto, me ducho, me visto, me peino.","es-g56-u03.w.0":"aufstehen","es-g56-u03.w.1":"duschen","es-g56-u03.w.2":"sich anziehen","es-g56-u03.w.3":"sich kämmen","es-g56-u03.w.4":"sich waschen","es-g56-u03.w.5":"ins Bett gehen","es-g56-u03.w.6":"aufwachen","es-g56-u03.w.7":"sich setzen","es-g56-u03.w.8":"Bürste (Zahnbürste)","es-g56-u03.w.9":"Handtuch","es-g56-u03.w.10":"Spiegel","es-g56-u03.w.11":"Schlafanzug","es-g56-u03.s.0":"Ich stehe um sieben auf.","es-g56-u03.s.1":"Ich dusche und ziehe mich schnell an.","es-g56-u03.s.2":"Mein Bruder kämmt sich vor dem Spiegel.","es-g56-u03.s.3":"Wir waschen uns vor dem Essen die Hände.","es-g56-u03.s.4":"Ich gehe um halb zehn ins Bett.","es-g56-u03.s.5":"Um wie viel Uhr wachst du auf?","es-g56-u03.s.6":"Die Kinder setzen sich auf den Boden.","es-g56-u03.s.7":"Ich trockne mich mit dem blauen Handtuch ab.","es-g56-u03.g.title":"Reflexive Verben: me levanto, te duchas, se viste","es-g56-u03.g.x.0":"Was man mit sich selbst macht, bekommt davor me, te, se, nos, se: Me levanto. Te duchas. Se viste.","es-g56-u03.g.x.1":"Hat die Grundform am Ende -se, ist das Verb reflexiv: levantarse, acostarse.","es-g56-u03.g.x.2":"Man kann es auch hinten an die Grundform hängen: Quiero levantarme. Voy a ducharme.","es-g56-u03.g.0":"Ich stehe um sieben auf.","es-g56-u03.g.1":"Duschst du morgens?","es-g56-u03.g.2":"Sie zieht sich allein an.","es-g56-u03.g.3":"Wir putzen uns die Zähne.","es-g56-u03.g.4":"Sie gehen spät ins Bett.","es-g56-u03.g.5":"Ich wache um sechs auf.","es-g56-u03.g.5.task":"Ändere den Satz in die „yo“-Form","es-g56-u03.g.6":"Wir setzen uns hierhin.","es-g56-u03.g.6.task":"Ändere den Satz in die „nosotros“-Form","es-g56-u03.g.7":"Ich will früh ins Bett gehen.","es-g56-u03.g.7.task":"Schreib den Satz mit „Quiero + Grundform“","es-g56-u03.r.ko":"Sofías Morgen","es-g56-u03.r.genre":"Alltagsgeschichte","es-g56-u03.r.p.0":"Sofía wacht um zehn vor sieben auf, steht aber erst um sieben auf. Zuerst duscht sie mit warmem Wasser und trocknet sich mit ihrem gelben Handtuch ab. Dann zieht sie sich an. Heute wählt sie eine blaue Hose und ein weißes T-Shirt.","es-g56-u03.r.p.1":"Im Bad putzt sie sich mit ihrer grünen Zahnbürste die Zähne und kämmt sich vor dem Spiegel. Ihr kleiner Bruder Hugo ist noch im Schlafanzug. „Beeil dich, Hugo!“, sagt Sofía. Hugo setzt sich aufs Bett und gähnt.","es-g56-u03.r.p.2":"Um acht frühstücken die beiden mit ihrer Mama. Abends geht Sofía um halb zehn ins Bett. Vor dem Einschlafen liest sie immer ein bisschen.","es-g56-u03.r.q.4.o.0":"gähnt","es-g56-u03.r.q.4.o.1":"singt","es-g56-u03.r.q.4.o.2":"rennt","es-g56-u03.r.q.4.o.3":"lacht","es-g56-u04.title":"Ich werde…: ir a + Grundform","es-g56-u04.tip":"Sag deine Wochenendpläne auf Spanisch: Voy a…, Vamos a…. Keine Pläne? No voy a hacer nada!","es-g56-u04.w.0":"reisen","es-g56-u04.w.1":"besuchen","es-g56-u04.w.2":"kaufen","es-g56-u04.w.3":"lernen","es-g56-u04.w.4":"schwimmen","es-g56-u04.w.5":"Koffer","es-g56-u04.w.6":"Ticket (Fahrkarte)","es-g56-u04.w.7":"Flughafen","es-g56-u04.w.8":"Hotel","es-g56-u04.w.9":"Landkarte","es-g56-u04.w.10":"nächster","es-g56-u04.w.11":"bald","es-g56-u04.s.0":"Ich werde nach Mexiko reisen.","es-g56-u04.s.1":"Wir werden unsere Großeltern besuchen.","es-g56-u04.s.2":"Wirst du ein Ticket kaufen?","es-g56-u04.s.3":"Meine Schwester wird Spanisch lernen.","es-g56-u04.s.4":"Nächsten Sommer werden wir viel schwimmen.","es-g56-u04.s.5":"Meine Eltern werden die Koffer packen.","es-g56-u04.s.6":"Wir werden bald am Flughafen ankommen.","es-g56-u04.s.7":"Ich werde nicht auf die Landkarte schauen.","es-g56-u04.g.title":"Ir a + Grundform: die nahe Zukunft","es-g56-u04.g.x.0":"„Ich werde…“ sagt man mit ir + a + Grundform: Voy a comer. Vas a leer. Va a dormir.","es-g56-u04.g.x.1":"Bei mehreren: Vamos a…, Van a…. Verneint: No voy a….","es-g56-u04.g.x.2":"Oft steht ein Zeitwort dabei: mañana (morgen), el próximo año (nächstes Jahr), pronto (bald), esta noche (heute Abend).","es-g56-u04.g.0":"Ich werde Brot kaufen.","es-g56-u04.g.1":"Wirst du im Sommer verreisen?","es-g56-u04.g.2":"Sie wird das Museum besuchen.","es-g56-u04.g.3":"Wir werden schwimmen.","es-g56-u04.g.4":"Sie werden bald ankommen.","es-g56-u04.g.5":"Morgen werde ich schwimmen lernen.","es-g56-u04.g.5.task":"Ändere den Satz zu „Mañana voy a…“","es-g56-u04.g.6":"Ich werde das Ticket nicht kaufen.","es-g56-u04.g.6.task":"Mach den Satz verneint (no)","es-g56-u04.g.7":"Wir werden unsere Großeltern besuchen.","es-g56-u04.g.7.task":"Setz den Satz mit „Vamos a…“ in die Zukunft","es-g56-u04.r.ko":"Die Reise der Familie Ruiz","es-g56-u04.r.genre":"Alltagsgeschichte","es-g56-u04.r.p.0":"Die Familie Ruiz wird nächsten Monat nach Peru reisen. Papa hat die Flugtickets schon, und Mama wird heute Abend das Hotel buchen. Diego, der zwölf ist, freut sich sehr, weil er Machu Picchu sehen wird.","es-g56-u04.r.p.1":"Seine Schwester Carla wird eine Landkarte und eine neue Kamera kaufen. „Ich werde tausend Fotos machen“, sagt sie. Diego wird vor der Reise zehn Wörter auf Quechua lernen. Am Freitag werden die beiden ihre Koffer packen.","es-g56-u04.r.p.2":"Am Samstag werden sie sehr früh zum Flughafen aufbrechen. „Wir werden nicht zu spät kommen“, sagt Papa. „Und wir werden die Pässe nicht vergessen!“","es-g56-u04.r.q.3.o.0":"buchen","es-g56-u04.r.q.3.o.1":"kaufen","es-g56-u04.r.q.3.o.2":"vergessen","es-g56-u04.r.q.3.o.3":"machen (Fotos)","es-g56-u05.title":"Gestern habe ich…: Vergangenheit der -ar-Verben","es-g56-u05.tip":"In der Vergangenheit endet yo auf -é und él auf -ó. Ohne Akzent ändert sich die Bedeutung: canto (ich singe) / cantó (er sang).","es-g56-u05.w.0":"gestern","es-g56-u05.w.1":"gestern Abend","es-g56-u05.w.2":"letzter (vergangen)","es-g56-u05.w.3":"gewinnen","es-g56-u05.w.4":"tanzen","es-g56-u05.w.5":"singen","es-g56-u05.w.6":"kochen","es-g56-u05.w.7":"putzen","es-g56-u05.w.8":"Spiel (Match)","es-g56-u05.w.9":"Mannschaft","es-g56-u05.w.10":"Ausflug","es-g56-u05.w.11":"Geburtstag","es-g56-u05.s.0":"Gestern habe ich mit meiner Mannschaft Fußball gespielt.","es-g56-u05.s.1":"Gestern Abend habe ich mit meinen Großeltern zu Abend gegessen.","es-g56-u05.s.2":"Hast du das Spiel gewonnen?","es-g56-u05.s.3":"Meine Schwester hat auf der Party getanzt.","es-g56-u05.s.4":"Wir haben an Lucías Geburtstag gesungen.","es-g56-u05.s.5":"Meine Eltern haben eine Paella gekocht.","es-g56-u05.s.6":"Letzten Samstag habe ich mein Zimmer geputzt.","es-g56-u05.s.7":"Der Ausflug endete um fünf.","es-g56-u05.g.title":"Vergangenheit der -ar-Verben: hablé, hablaste, habló","es-g56-u05.g.x.0":"Für abgeschlossene Dinge benutzt man die Vergangenheit (pretérito). Verben auf -ar: habl-é, habl-aste, habl-ó, habl-amos, habl-aron.","es-g56-u05.g.x.1":"Yo endet auf -é, él/ella auf -ó. Der Akzent muss sein: canté, cantó.","es-g56-u05.g.x.2":"Nosotros sieht aus wie im Präsens (hablamos). Wörter wie ayer oder anoche zeigen, dass es Vergangenheit ist.","es-g56-u05.g.x.3":"Jugar schreibt man bei yo als jugué (das u erhält den Klang).","es-g56-u05.g.0":"Gestern habe ich im Unterricht gesungen.","es-g56-u05.g.1":"Hast du gestern Abend getanzt?","es-g56-u05.g.2":"Mein Papa hat das Abendessen gekocht.","es-g56-u05.g.3":"Wir haben gestern das Haus geputzt.","es-g56-u05.g.4":"Sie haben das Spiel gewonnen.","es-g56-u05.g.5":"Gestern habe ich Fußball gespielt.","es-g56-u05.g.5.task":"Setz den Satz mit „Ayer“ in die Vergangenheit","es-g56-u05.g.6":"Sie hat mit der Lehrerin gesprochen.","es-g56-u05.g.6.task":"Setz den Satz in die Vergangenheit","es-g56-u05.g.7":"Wir sind letztes Jahr mit dem Zug gereist.","es-g56-u05.g.7.task":"Ändere den Satz so, dass er mit „Nosotros“ beginnt","es-g56-u06.title":"Gegessen, gelebt: Vergangenheit der -er/-ir-Verben","es-g56-u06.tip":"Die Vergangenheit von -er und -ir ist völlig gleich: comí/viví, comiste/viviste… Ein Satz Endungen reicht für beide!","es-g56-u06.w.0":"verlieren","es-g56-u06.w.1":"zerbrechen","es-g56-u06.w.2":"lernen","es-g56-u06.w.3":"rennen","es-g56-u06.w.4":"öffnen","es-g56-u06.w.5":"bekommen","es-g56-u06.w.6":"schreiben","es-g56-u06.w.7":"hinaufsteigen","es-g56-u06.w.8":"Treppe","es-g56-u06.w.9":"Preis (Belohnung)","es-g56-u06.w.10":"Wettbewerb","es-g56-u06.w.11":"Überraschung","es-g56-u06.s.0":"Gestern habe ich im Park meine Kappe verloren.","es-g56-u06.s.1":"Mein Bruder hat ein Glas zerbrochen.","es-g56-u06.s.2":"Wir haben ein neues Lied gelernt.","es-g56-u06.s.3":"Bist du beim Wettrennen mitgelaufen?","es-g56-u06.s.4":"Ich öffnete die Tür und sah eine Überraschung.","es-g56-u06.s.5":"Lucía hat beim Wettbewerb einen Preis bekommen.","es-g56-u06.s.6":"Ich habe meinem Opa einen Brief geschrieben.","es-g56-u06.s.7":"Wir sind die Treppe hinaufgerannt.","es-g56-u06.g.title":"Vergangenheit der -er / -ir-Verben: comí, comiste, comió","es-g56-u06.g.x.0":"Die Vergangenheit von -er- und -ir-Verben ist gleich: com-í, com-iste, com-ió, com-imos, com-ieron.","es-g56-u06.g.x.1":"viv-í, viv-iste, viv-ió, viv-imos, viv-ieron.","es-g56-u06.g.x.2":"Yo endet auf -í, él/ella auf -ió. Vergiss den Akzent nicht: perdí, perdió.","es-g56-u06.g.0":"Gestern habe ich Paella gegessen.","es-g56-u06.g.1":"Hast du den Schlüssel verloren?","es-g56-u06.g.2":"Er hat das Fenster zerbrochen.","es-g56-u06.g.3":"Wir haben viel gelernt.","es-g56-u06.g.4":"Sie haben die Geschenke geöffnet.","es-g56-u06.g.5":"Sie hat einen Preis bekommen.","es-g56-u06.g.5.task":"Setz den Satz in die Vergangenheit","es-g56-u06.g.6":"Ich habe einen Brief geschrieben.","es-g56-u06.g.6.task":"Setz den Satz in die Vergangenheit","es-g56-u06.g.7":"Wir sind gestern auf den Berg gestiegen.","es-g56-u06.g.7.task":"Ändere den Satz so, dass er mit „Nosotros“ beginnt","es-g56-u06.r.ko":"Der Malwettbewerb","es-g56-u06.r.genre":"Kurzgeschichte","es-g56-u06.r.p.0":"Letzten Montag gab es in der Schule einen Malwettbewerb. Lucía malte einen grünen Drachen mit riesigen Flügeln. Pablo malte seinen Hund Toby, brach aber aus Versehen seinen roten Stift ab und bat die Lehrerin um einen anderen.","es-g56-u06.r.p.1":"Am Ende des Nachmittags öffnete die Schulleiterin einen Umschlag und las die Namen vor. „Der erste Preis geht an… Lucía!“ Lucía bekam eine Schachtel Buntstifte und ein Buch. Pablo gewann nicht, aber er lernte etwas Wichtiges: sorgfältig malen.","es-g56-u06.r.p.2":"An dem Abend schrieb Lucía ihrer Oma einen Brief. „Oma, ich habe den Wettbewerb gewonnen. Es war eine riesige Überraschung!“ Und Pablo beschloss, fürs nächste Jahr einen Drachen zu malen.","es-g56-u07.title":"Iss! Mach auf!: Befehlsform","es-g56-u07.tip":"Befehle sind kurz und kräftig! Probier sie zu Hause aus: ¡Ven! ¡Mira! ¡Escucha! (Mit por favor dahinter klingen sie noch netter.)","es-g56-u07.w.0":"zuhören","es-g56-u07.w.1":"schauen","es-g56-u07.w.2":"warten","es-g56-u07.w.3":"schließen","es-g56-u07.w.4":"nehmen (trinken)","es-g56-u07.w.5":"reichen (vorbeigehen)","es-g56-u07.w.6":"Vorsicht","es-g56-u07.w.7":"Stille","es-g56-u07.w.8":"langsam","es-g56-u07.w.9":"Salz","es-g56-u07.w.10":"Rezept","es-g56-u07.w.11":"Anweisung","es-g56-u07.s.0":"Hör der Lehrerin zu.","es-g56-u07.s.1":"Schau bitte auf die Karte.","es-g56-u07.s.2":"Warte einen Moment.","es-g56-u07.s.3":"Mach das Fenster zu, es ist kalt.","es-g56-u07.s.4":"Trink ein Glas Wasser.","es-g56-u07.s.5":"Reich mir bitte das Salz.","es-g56-u07.s.6":"Sprich langsam und vorsichtig.","es-g56-u07.s.7":"Lies das Rezept, bevor du kochst.","es-g56-u07.g.title":"Befehle an tú: ¡Habla! ¡Come! ¡Abre!","es-g56-u07.g.x.0":"Wenn du einem Freund sagst „Mach das!“, nimmst du die él/ella-Form des Präsens: habla, come, abre, escucha, cierra.","es-g56-u07.g.x.1":"Ein paar unregelmäßige musst du lernen: ten (nimm), ven (komm), pon (leg), sal (geh raus), haz (mach), di (sag).","es-g56-u07.g.x.2":"Wörter wie me oder la hängst du hinten dran: Pásame la sal. Ciérrala.","es-g56-u07.g.0":"Hör dir das Lied an!","es-g56-u07.g.1":"Iss das Obst!","es-g56-u07.g.2":"Mach das Buch auf!","es-g56-u07.g.3":"Komm her, bitte!","es-g56-u07.g.4":"Deck den Tisch!","es-g56-u07.g.5":"Mach die Tür zu!","es-g56-u07.g.5.task":"Mach daraus einen Befehl","es-g56-u07.g.6":"Schau auf die Karte!","es-g56-u07.g.6.task":"Mach daraus einen Befehl","es-g56-u07.g.7":"Mach jetzt deine Hausaufgaben!","es-g56-u07.g.7.task":"Mach daraus einen Befehl","es-g56-u08.title":"Größer, weniger teuer: vergleichen","es-g56-u08.tip":"Vergleich deine Familie und Freunde: Mi papá es más alto que mi mamá. Soy tan rápido como mi amigo.","es-g56-u08.w.0":"mehr","es-g56-u08.w.1":"weniger","es-g56-u08.w.2":"besser","es-g56-u08.w.3":"schlechter","es-g56-u08.w.4":"älter","es-g56-u08.w.5":"jünger","es-g56-u08.w.6":"breit","es-g56-u08.w.7":"eng","es-g56-u08.w.8":"laut","es-g56-u08.w.9":"ruhig","es-g56-u08.w.10":"Gebäude","es-g56-u08.w.11":"Einwohner","es-g56-u08.s.0":"Madrid ist größer als Toledo.","es-g56-u08.s.1":"Das Dorf ist weniger laut als die Stadt.","es-g56-u08.s.2":"Mein Bruder ist älter als ich.","es-g56-u08.s.3":"Dieses Buch ist besser als das da.","es-g56-u08.s.4":"Die Straße ist so eng wie ein Flur.","es-g56-u08.s.5":"Ich habe so viele Stifte wie du.","es-g56-u08.s.6":"Das neue Gebäude ist höher als die Kirche.","es-g56-u08.s.7":"Mein jüngerer Cousin rennt schneller als ich.","es-g56-u08.g.title":"Vergleiche: más … que, menos … que, tan … como","es-g56-u08.g.x.0":"„Mehr/-er als“: más + Adjektiv + que. Soy más alto que tú.","es-g56-u08.g.x.1":"„Weniger … als“: menos + Adjektiv + que. „So … wie“: tan + Adjektiv + como.","es-g56-u08.g.x.2":"Besondere Formen: bueno → mejor, malo → peor, grande (Alter) → mayor, pequeño (Alter) → menor.","es-g56-u08.g.0":"Der Löwe ist größer als die Katze.","es-g56-u08.g.1":"Der Zug ist weniger schnell als das Flugzeug.","es-g56-u08.g.2":"Mein Haus ist so schön wie deins.","es-g56-u08.g.3":"Dieses Eis ist besser als das da.","es-g56-u08.g.4":"Meine Schwester ist älter als ich.","es-g56-u08.g.5":"Die Stadt ist lauter als das Dorf.","es-g56-u08.g.5.task":"Schreib den Satz als „La ciudad … ruidosa“","es-g56-u08.g.6":"Heute ist es weniger kalt als gestern.","es-g56-u08.g.6.task":"Schreib den Satz mit „menos“ (weniger)","es-g56-u08.g.7":"Ich bin so groß wie mein Cousin.","es-g56-u08.g.7.task":"Schreib den Satz mit „tan … como“ (so … wie)","es-g56-u08.r.ko":"Zwei Städte, zwei Cousins","es-g56-u08.r.genre":"Sachtext","es-g56-u08.r.p.0":"Javier lebt in Madrid und seine Cousine Elena lebt in Cuenca. Madrid ist viel größer als Cuenca: Es hat mehr als drei Millionen Einwohner, Cuenca weniger als sechzigtausend. In Madrid gibt es höhere Gebäude, breitere Straßen und viel mehr Lärm.","es-g56-u08.r.p.1":"Cuenca ist ruhiger und älter. Die Straßen sind so eng, dass manchmal kein Auto durchpasst. Elena sagt, die Luft in Cuenca sei besser als in Madrid. Javier sagt, Madrid sei spannender, weil es mehr Museen und mehr Parks hat.","es-g56-u08.r.p.2":"Die beiden Cousins sind gleich alt und so gute Freunde wie Geschwister. Im Sommer besucht Javier Cuenca, und im Winter besucht Elena Madrid. So lernen beide das Beste jeder Stadt kennen.","es-g56-u08.r.q.3.o.0":"alt","es-g56-u08.r.q.3.o.1":"laut","es-g56-u08.r.q.3.o.2":"breit","es-g56-u08.r.q.3.o.3":"neu","es-g56-u09.title":"Der größte, der beste: Superlativ","es-g56-u09.tip":"Sag Weltrekorde auf Spanisch: el más alto, el más rápido, el más grande del mundo.","es-g56-u09.w.0":"lang","es-g56-u09.w.1":"kurz","es-g56-u09.w.2":"tief","es-g56-u09.w.3":"berühmt","es-g56-u09.w.4":"uralt","es-g56-u09.w.5":"modern","es-g56-u09.w.6":"köstlich","es-g56-u09.w.7":"gefährlich","es-g56-u09.w.8":"Welt","es-g56-u09.w.9":"Planet","es-g56-u09.w.10":"Tier","es-g56-u09.w.11":"Wüste","es-g56-u09.s.0":"Der Nil ist der längste Fluss der Welt.","es-g56-u09.s.1":"Jupiter ist der größte Planet.","es-g56-u09.s.2":"Der Blauwal ist das schwerste Tier.","es-g56-u09.s.3":"Das ist die köstlichste Pizza der Stadt.","es-g56-u09.s.4":"Meine Oma ist der freundlichste Mensch, den ich kenne.","es-g56-u09.s.5":"Das ist das älteste Gebäude im Ort.","es-g56-u09.s.6":"Die Sahara ist die berühmteste Wüste.","es-g56-u09.s.7":"Das ist der am wenigsten gefährliche Weg.","es-g56-u09.g.title":"Superlativ: el/la más … de","es-g56-u09.g.x.0":"„Der/die … -ste“ heißt el/la/los/las + más + Adjektiv: el río más largo, la casa más bonita.","es-g56-u09.g.x.1":"„In/von“ einer Gruppe heißt de: el más alto de la clase (der Größte in der Klasse).","es-g56-u09.g.x.2":"„Am wenigsten …“ heißt menos. Besondere Formen: el mejor (der beste), el peor (der schlechteste), el mayor (der älteste).","es-g56-u09.g.0":"Es ist der längste Fluss der Welt.","es-g56-u09.g.1":"Es ist die älteste Stadt Spaniens.","es-g56-u09.g.2":"Sie ist die beste Spielerin der Mannschaft.","es-g56-u09.g.3":"Es ist das gefährlichste Tier im Meer.","es-g56-u09.g.4":"Mein Bruder ist der Älteste in der Familie.","es-g56-u09.g.5":"Es ist der am wenigsten gefährliche Weg.","es-g56-u09.g.5.task":"Schreib den Satz mit „menos“ (am wenigsten)","es-g56-u09.g.6":"Es ist der höchste Berg des Landes.","es-g56-u09.g.6.task":"Mach daraus den Superlativ „la … más alta del país“","es-g56-u09.g.7":"Es ist der köstlichste Kuchen auf der Party.","es-g56-u09.g.7.task":"Mach daraus den Superlativ „el … más delicioso de la fiesta“","es-g56-u10.title":"Ich sehe es: lo, la, los, las","es-g56-u10.tip":"Schau auf Geschlecht und Zahl der Sache: el libro → lo, la carta → la, los lápices → los, las gafas → las.","es-g56-u10.w.0":"suchen","es-g56-u10.w.1":"mitnehmen (tragen)","es-g56-u10.w.2":"benutzen","es-g56-u10.w.3":"aufbewahren","es-g56-u10.w.4":"leihen","es-g56-u10.w.5":"brauchen","es-g56-u10.w.6":"einladen","es-g56-u10.w.7":"Computer","es-g56-u10.w.8":"Kamera","es-g56-u10.w.9":"Brille","es-g56-u10.w.10":"Regenschirm","es-g56-u10.w.11":"Geldbörse","es-g56-u10.s.0":"Wo ist meine Geldbörse? Ich finde sie nicht.","es-g56-u10.s.1":"Ich brauche den Regenschirm. Ich nehme ihn heute mit.","es-g56-u10.s.2":"Die Brille? Ich bewahre sie im Rucksack auf.","es-g56-u10.s.3":"Meine Cousins kommen. Ich lade sie zum Abendessen ein.","es-g56-u10.s.4":"Leihst du mir deine Kamera? Ich brauche sie.","es-g56-u10.s.5":"Der Computer ist alt, aber ich benutze ihn jeden Tag.","es-g56-u10.s.6":"Ich suche meine Schlüssel. Siehst du sie?","es-g56-u10.s.7":"Ich lade dich zu meiner Party ein.","es-g56-u10.g.title":"Objektpronomen: lo, la, los, las, me, te","es-g56-u10.g.x.0":"Damit man nichts wiederholt, heißt „es/ihn/sie“ lo (männlich) oder la (weiblich), in der Mehrzahl los/las: ¿El libro? Lo leo. ¿La carta? La escribo.","es-g56-u10.g.x.1":"„Mich“ heißt me, „dich“ heißt te: Te invito. Me buscas.","es-g56-u10.g.x.2":"Das Pronomen steht vor dem Verb. Bei einer Grundform kann man es auch hinten anhängen: Quiero comprarlo.","es-g56-u10.g.0":"Das Buch? Ich lese es heute Abend.","es-g56-u10.g.1":"Der Brief? Ich schreibe ihn morgen.","es-g56-u10.g.2":"Die Stifte? Ich bewahre sie hier auf.","es-g56-u10.g.3":"Die Brille? Ich brauche sie.","es-g56-u10.g.4":"Ich lade dich zu mir nach Hause ein.","es-g56-u10.g.5":"Der Regenschirm? Ich nehme ihn mit.","es-g56-u10.g.5.task":"Ersetze „el paraguas“ durch lo","es-g56-u10.g.6":"Die Kamera? Ich benutze sie viel.","es-g56-u10.g.6.task":"Ersetze „la cámara“ durch la","es-g56-u10.g.7":"Die Cousins? Ich lade sie ein.","es-g56-u10.g.7.task":"Ersetze „los primos“ durch los","es-g56-u11.title":"Gerade jetzt: estar + -ando/-iendo","es-g56-u11.tip":"Schau dich um und beschreib: Mamá está cocinando. El perro está durmiendo. ¿Qué estás haciendo tú?","es-g56-u11.w.0":"jetzt","es-g56-u11.w.1":"noch","es-g56-u11.w.2":"vorbereiten","es-g56-u11.w.3":"bauen","es-g56-u11.w.4":"malen (streichen)","es-g56-u11.w.5":"spielen (Instrument), anfassen","es-g56-u11.w.6":"lachen","es-g56-u11.w.7":"weinen","es-g56-u11.w.8":"Jahrmarkt","es-g56-u11.w.9":"Gitarre","es-g56-u11.w.10":"Clown","es-g56-u11.w.11":"Luftballon","es-g56-u11.s.0":"Gerade mache ich meine Hausaufgaben.","es-g56-u11.s.1":"Was isst du gerade?","es-g56-u11.s.2":"Mama bereitet gerade das Abendessen vor.","es-g56-u11.s.3":"Die Kinder bauen gerade eine Sandburg.","es-g56-u11.s.4":"Mein Bruder spielt gerade Gitarre.","es-g56-u11.s.5":"Der Clown lacht gerade mit den Kindern.","es-g56-u11.s.6":"Wir streichen noch die Wand.","es-g56-u11.s.7":"Das Baby weint, weil es seinen Luftballon verloren hat.","es-g56-u11.g.title":"Verlaufsform: estar + -ando / -iendo","es-g56-u11.g.x.0":"„Ich bin gerade dabei“ sagt man mit estar + Verb auf -ando (-ar) / -iendo (-er, -ir): Estoy hablando. Estás comiendo. Está escribiendo.","es-g56-u11.g.x.1":"Ein i zwischen Vokalen wird zu y: leer → leyendo, construir → construyendo. Außerdem dormir → durmiendo, reír → riendo.","es-g56-u11.g.x.2":"Nur estar ändert sich mit der Person; -ando/-iendo bleibt gleich.","es-g56-u11.g.0":"Ich rede gerade mit Mama.","es-g56-u11.g.1":"Isst du gerade?","es-g56-u11.g.2":"Sie schreibt gerade einen Brief.","es-g56-u11.g.3":"Wir lesen gerade ein Buch.","es-g56-u11.g.4":"Sie bauen gerade ein Haus.","es-g56-u11.g.5":"Mein Bruder schläft gerade.","es-g56-u11.g.5.task":"Setz den Satz in die Verlaufsform (gerade jetzt)","es-g56-u11.g.6":"Gerade streiche ich die Tür.","es-g56-u11.g.6.task":"Setz den Satz in die Verlaufsform „Ahora estoy…“","es-g56-u11.g.7":"Die Kinder lachen gerade.","es-g56-u11.g.7.task":"Setz den Satz in die Verlaufsform (gerade jetzt)","es-g56-u11.r.ko":"Der Jahrmarkt im Dorf","es-g56-u11.r.genre":"Beschreibung","es-g56-u11.r.p.0":"Es ist Samstagnachmittag und der Jahrmarkt im Dorf ist voller Menschen. Auf dem Platz macht ein Clown mit roter Nase Tiere aus Luftballons. Die Kinder lachen und rufen: „Ein Hund! Eine Giraffe!“","es-g56-u11.r.p.1":"Beim Brunnen spielen drei Musiker Gitarre, und eine Frau singt ein altes Lied. Mein Opa tanzt mit meiner Oma. Meine Mama macht an einem Stand heiße Schokolade, und mein Papa kauft Churros.","es-g56-u11.r.p.2":"Ich sitze mit meiner kleinen Schwester auf einer Bank. Sie malt in ihr Heft, was sie sieht. Ein Baby weint, weil sein Luftballon in den Himmel fliegt. Alle schauen dem Ballon nach!","es-g56-u11.r.q.3.o.0":"Stand","es-g56-u11.r.q.3.o.1":"Brunnen","es-g56-u11.r.q.3.o.2":"Bank","es-g56-u11.r.q.3.o.3":"Platz","es-g56-u12.title":"Ging, machte, war: unregelmäßige Vergangenheit","es-g56-u12.tip":"Die Vergangenheit von ir und ser ist gleich: fui! Der Zusammenhang hilft: Fui al cine (ich ging) / Fui feliz (ich war).","es-g56-u12.w.0":"geboren werden","es-g56-u12.w.1":"aufwachsen","es-g56-u12.w.2":"erfinden","es-g56-u12.w.3":"entdecken","es-g56-u12.w.4":"Maler","es-g56-u12.w.5":"Wissenschaftlerin","es-g56-u12.w.6":"Jahrhundert","es-g56-u12.w.7":"Geschichte","es-g56-u12.w.8":"Reise","es-g56-u12.w.9":"Schiff","es-g56-u12.w.10":"König","es-g56-u12.w.11":"Gemälde","es-g56-u12.s.0":"Gestern bin ich mit meiner Klasse ins Museum gegangen.","es-g56-u12.s.1":"Picasso war ein sehr berühmter Maler.","es-g56-u12.s.2":"Marie Curie machte wichtige Entdeckungen.","es-g56-u12.s.3":"Kolumbus machte eine lange Reise mit dem Schiff.","es-g56-u12.s.4":"Mein Opa hatte ein glückliches Leben.","es-g56-u12.s.5":"Wo warst du gestern?","es-g56-u12.s.6":"Der König lebte im 15. Jahrhundert.","es-g56-u12.s.7":"Wir gingen ein altes Gemälde anschauen.","es-g56-u12.g.title":"Unregelmäßige Vergangenheit: fui, hice, tuve, estuve","es-g56-u12.g.x.0":"Ir und ser haben dieselbe Vergangenheit: fui, fuiste, fue, fuimos, fueron. (ging / war)","es-g56-u12.g.x.1":"Hacer: hice, hiciste, hizo, hicimos, hicieron. Tener: tuve, tuviste, tuvo, tuvimos, tuvieron.","es-g56-u12.g.x.2":"Estar: estuve, estuviste, estuvo, estuvimos, estuvieron. Diese Vergangenheitsformen haben keinen Akzent.","es-g56-u12.g.0":"Gestern bin ich in den Park gegangen.","es-g56-u12.g.1":"Picasso war ein großer Maler.","es-g56-u12.g.2":"Was hast du am Sonntag gemacht?","es-g56-u12.g.3":"Sie hat einen Kuchen gemacht.","es-g56-u12.g.4":"Wir hatten einen Test.","es-g56-u12.g.5":"Ich war gestern Abend zu Hause.","es-g56-u12.g.5.task":"Setz den Satz mit „anoche“ in die Vergangenheit","es-g56-u12.g.6":"Sie sind zum Strand gegangen.","es-g56-u12.g.6.task":"Setz den Satz in die Vergangenheit","es-g56-u12.g.7":"Meine Oma hatte fünf Kinder.","es-g56-u12.g.7.task":"Setz den Satz in die Vergangenheit","es-g56-u12.r.ko":"Frida Kahlo, die Malerin der Farben","es-g56-u12.r.genre":"Biografie","es-g56-u12.r.p.0":"Frida Kahlo wurde 1907 in Mexiko geboren. Als Kind war sie krank, und einige Jahre später hatte sie einen schweren Busunfall. Viele Monate lang lag sie im Bett. Ihr Vater schenkte ihr Farben und einen Spiegel, und so begann Frida zu malen.","es-g56-u12.r.p.1":"Frida malte viele Bilder von sich selbst, mit Blumen im Haar und sehr kräftigen Farben. Sie malte auch Tiere: Affen, Hunde und Papageien, die in ihrem blauen Haus lebten. Sie reiste in die USA und nach Frankreich, und ihre Bilder wurden auf der ganzen Welt berühmt.","es-g56-u12.r.p.2":"Frida starb 1954, aber ihr blaues Haus ist heute ein Museum. Jedes Jahr kommen Tausende Menschen dorthin, um ihre Bilder und ihren Garten zu sehen.","es-g56-u12.r.q.4.o.0":"schlimm","es-g56-u12.r.q.4.o.1":"klein","es-g56-u12.r.q.4.o.2":"lustig","es-g56-u12.r.q.4.o.3":"blau","es-g56-u13.title":"Ich weiß, ich kenne: saber und conocer","es-g56-u13.tip":"„Ich kann (etwas tun)“ ist immer saber: Sé nadar. „Ich war schon dort, ich kenne jemanden“ ist conocer.","es-g56-u13.w.0":"wissen (Wissen, Können)","es-g56-u13.w.1":"kennen (Leute, Orte)","es-g56-u13.w.2":"Antwort","es-g56-u13.w.3":"Adresse (Richtung)","es-g56-u13.w.4":"Weg","es-g56-u13.w.5":"Sprache","es-g56-u13.w.6":"Nachbarin","es-g56-u13.w.7":"Geheimnis","es-g56-u13.w.8":"Nummer (Zahl)","es-g56-u13.w.9":"fahren (Rad)","es-g56-u13.w.10":"spielen (Instrument)","es-g56-u13.w.11":"Hauptstadt","es-g56-u13.s.0":"Ich kann schwimmen und Fahrrad fahren.","es-g56-u13.s.1":"Weißt du die Antwort?","es-g56-u13.s.2":"Ich kenne deine Nachbarin, sie ist sehr freundlich.","es-g56-u13.s.3":"Ich kenne Barcelona noch nicht.","es-g56-u13.s.4":"Meine Tante kann drei Sprachen.","es-g56-u13.s.5":"Weißt du, was die Hauptstadt von Peru ist?","es-g56-u13.s.6":"Ich weiß deine Telefonnummer nicht.","es-g56-u13.s.7":"Ich weiß ein Geheimnis, aber ich verrate es nicht.","es-g56-u13.g.title":"Saber (Wissen, Können) und conocer (Leute, Orte)","es-g56-u13.g.x.0":"Wenn du eine Information weißt oder etwas kannst: saber. Sé la respuesta. Sé nadar. (sé, sabes, sabe, sabemos, saben)","es-g56-u13.g.x.1":"Wenn du Leute oder Orte kennst (dort warst): conocer. Conozco a Lucía. Conozco Madrid. (conozco, conoces, conoce…)","es-g56-u13.g.x.2":"Vor einer Person steht a: Conozco a tu hermano.","es-g56-u13.g.0":"Ich weiß die Antwort.","es-g56-u13.g.1":"Ich kenne deine Lehrerin.","es-g56-u13.g.2":"Kannst du schwimmen?","es-g56-u13.g.3":"Sie kennt Madrid sehr gut.","es-g56-u13.g.4":"Wir wissen die Adresse.","es-g56-u13.g.5":"Ich kenne deine Nachbarin.","es-g56-u13.g.5.task":"Schreib den Satz mit „a tu vecina“ (eine Person)","es-g56-u13.g.6":"Ich kann nicht Gitarre spielen.","es-g56-u13.g.6.task":"Mach den Satz verneint (no)","es-g56-u13.g.7":"Weißt du, was die Hauptstadt ist?","es-g56-u13.g.7.task":"Mach daraus eine Frage mit „¿Tú…?“","es-g56-u14.title":"Tu das nicht!: verneinte Befehle","es-g56-u14.tip":"Positiv heißt es habla/come, verneint no hables/no comas – merk dir: Der Vokal tauscht.","es-g56-u14.w.0":"schreien","es-g56-u14.w.1":"anfassen","es-g56-u14.w.2":"rennen","es-g56-u14.w.3":"vergessen","es-g56-u14.w.4":"stören","es-g56-u14.w.5":"wegwerfen","es-g56-u14.w.6":"verboten","es-g56-u14.w.7":"Regel","es-g56-u14.w.8":"Flur","es-g56-u14.w.9":"Müll","es-g56-u14.w.10":"Mülleimer","es-g56-u14.w.11":"Schild (Plakat)","es-g56-u14.s.0":"Schrei nicht in der Bibliothek.","es-g56-u14.s.1":"Fass das Bild bitte nicht an.","es-g56-u14.s.2":"Renn nicht im Flur.","es-g56-u14.s.3":"Vergiss deinen Rucksack nicht.","es-g56-u14.s.4":"Stör den Hund nicht, wenn er frisst.","es-g56-u14.s.5":"Wirf keinen Müll auf den Boden.","es-g56-u14.s.6":"Im Unterricht zu essen ist verboten.","es-g56-u14.s.7":"Auf dem Schild steht: „Eintritt verboten“.","es-g56-u14.g.title":"Verneinte Befehle: No hables. No comas. No abras.","es-g56-u14.g.x.0":"„Tu das nicht“ heißt no + eine besondere Form: -ar-Verben bekommen -es, -er/-ir-Verben -as. No hables. No comas. No abras.","es-g56-u14.g.x.1":"Der Vokal ist umgekehrt wie beim positiven Befehl: ¡Habla! ↔ No hables. ¡Come! ↔ No comas.","es-g56-u14.g.x.2":"Manchmal ändert sich die Schreibweise, damit der Klang bleibt: tocar → No toques. jugar → No juegues.","es-g56-u14.g.0":"Schrei nicht, bitte.","es-g56-u14.g.1":"Iss nicht im Unterricht.","es-g56-u14.g.2":"Mach das Fenster nicht auf.","es-g56-u14.g.3":"Fass das nicht an.","es-g56-u14.g.4":"Spiel nicht mit Feuer.","es-g56-u14.g.5":"Renn nicht im Flur.","es-g56-u14.g.5.task":"Mach daraus einen verneinten Befehl („nicht“)","es-g56-u14.g.6":"Vergiss den Regenschirm nicht.","es-g56-u14.g.6.task":"Mach daraus einen verneinten Befehl („nicht“)","es-g56-u14.g.7":"Wirf kein Papier auf den Boden.","es-g56-u14.g.7.task":"Mach daraus einen verneinten Befehl („nicht“)","es-g56-u15.title":"Por und para","es-g56-u15.tip":"Para schaut nach vorn (Zweck, Ziel), por schaut zurück (Grund). „Es para ti“ / „Gracias por venir“.","es-g56-u15.w.0":"Geschenk","es-g56-u15.w.1":"Grund","es-g56-u15.w.2":"Ziel","es-g56-u15.w.3":"Fenster","es-g56-u15.w.4":"Post (E-Mail)","es-g56-u15.w.5":"Nachmittag","es-g56-u15.w.6":"Woche","es-g56-u15.w.7":"Preis","es-g56-u15.w.8":"Euro","es-g56-u15.w.9":"Zug","es-g56-u15.w.10":"Wald","es-g56-u15.w.11":"Morgen (morgen)","es-g56-u15.s.0":"Dieses Geschenk ist für dich.","es-g56-u15.s.1":"Ich lerne Spanisch, um nach Mexiko zu reisen.","es-g56-u15.s.2":"Danke für deine Hilfe.","es-g56-u15.s.3":"Wir gehen durch den Wald.","es-g56-u15.s.4":"Ich habe das Buch für zehn Euro gekauft.","es-g56-u15.s.5":"Nachmittags spiele ich Fußball.","es-g56-u15.s.6":"Die Hausaufgaben sind für Montag.","es-g56-u15.s.7":"Ich schicke den Brief mit der Post.","es-g56-u15.g.title":"Por (Grund, hindurch, Preis) und para (Zweck, Empfänger, Frist)","es-g56-u15.g.x.0":"Para = „für, um zu, bis“: Es para ti. Estudio para aprender. Es para el lunes.","es-g56-u15.g.x.1":"Por = „wegen, durch, für (Preis)“: Gracias por todo. Paso por el parque. Lo compré por dos euros.","es-g56-u15.g.x.2":"Tageszeiten nehmen por: por la mañana, por la tarde, por la noche.","es-g56-u15.g.0":"Dieses Geschenk ist für meine Oma.","es-g56-u15.g.1":"Danke für das Geschenk.","es-g56-u15.g.2":"Ich lerne, um Arzt zu werden.","es-g56-u15.g.3":"Wir gehen am Strand entlang.","es-g56-u15.g.4":"Morgens frühstücke ich.","es-g56-u15.g.5":"Die Hausaufgaben sind für morgen.","es-g56-u15.g.5.task":"Ersetze das falsche por durch das richtige Wort","es-g56-u15.g.6":"Ich habe es für fünf Euro gekauft.","es-g56-u15.g.6.task":"Ersetze das falsche para durch das richtige Wort","es-g56-u15.g.7":"Ich reise, um meine Cousins zu sehen.","es-g56-u15.g.7.task":"Ersetze das falsche por durch das richtige Wort","es-g56-u16.title":"Zuerst, dann, schließlich: eine Geschichte erzählen","es-g56-u16.tip":"Erzähl deine Lieblingsgeschichte in drei Sätzen mit primero, luego, finalmente.","es-g56-u16.w.0":"zuerst","es-g56-u16.w.1":"dann","es-g56-u16.w.2":"danach","es-g56-u16.w.3":"schließlich","es-g56-u16.w.4":"während","es-g56-u16.w.5":"plötzlich","es-g56-u16.w.6":"Fuchs","es-g56-u16.w.7":"Rabe","es-g56-u16.w.8":"Käse","es-g56-u16.w.9":"Ast","es-g56-u16.w.10":"Schnabel","es-g56-u16.w.11":"Lehre (Moral)","es-g56-u16.s.0":"Zuerst fand der Rabe ein Stück Käse.","es-g56-u16.s.1":"Dann setzte er sich auf einen hohen Ast.","es-g56-u16.s.2":"Plötzlich kam ein Fuchs.","es-g56-u16.s.3":"Während er redete, schaute der Fuchs auf den Käse.","es-g56-u16.s.4":"Der Rabe öffnete den Schnabel, um zu singen.","es-g56-u16.s.5":"Der Käse fiel auf den Boden.","es-g56-u16.s.6":"Schließlich fraß der Fuchs den Käse.","es-g56-u16.s.7":"Die Lehre ist: Glaub nicht jedem schönen Wort.","es-g56-u16.g.title":"Erzählwörter: primero, luego, después, finalmente, mientras, de repente","es-g56-u16.g.x.0":"Für die Reihenfolge: primero (zuerst) → luego/después (dann) → finalmente (schließlich).","es-g56-u16.g.x.1":"Mientras heißt „während“, de repente heißt „plötzlich“. Damit wird eine Geschichte lebendig.","es-g56-u16.g.x.2":"Diese Wörter stehen meist am Satzanfang mit einem Komma: Primero, … Luego, … Finalmente, ….","es-g56-u16.g.0":"Zuerst stehe ich früh auf.","es-g56-u16.g.1":"Dann frühstücke ich mit meiner Familie.","es-g56-u16.g.2":"Schließlich gehe ich los zur Schule.","es-g56-u16.g.3":"Ich singe, während ich dusche.","es-g56-u16.g.4":"Plötzlich fing es an zu regnen.","es-g56-u16.g.5":"Nach dem Abendessen lese ich eine Geschichte.","es-g56-u16.g.5.task":"Schreib den Satz mit „después de“ (nach)","es-g56-u16.g.6":"Zuerst sah der Fuchs den Käse.","es-g56-u16.g.6.task":"Setz „Primero,“ an den Anfang","es-g56-u16.g.7":"Schließlich verlor der Rabe den Käse.","es-g56-u16.g.7.task":"Setz „Finalmente,“ an den Anfang","es-g56-u16.r.ko":"Der Fuchs und der Rabe","es-g56-u16.r.genre":"Fabel","es-g56-u16.r.p.0":"Eines Morgens fand ein Rabe am Fenster eines Hauses ein Stück Käse. Er nahm es in den Schnabel und flog auf den höchsten Ast eines Baumes. Er war sehr zufrieden und wollte es in Ruhe essen.","es-g56-u16.r.p.1":"Plötzlich kam ein Fuchs vorbei und sah den Käse. „Guten Morgen, Herr Rabe“, sagte er. „Was für wunderschöne Federn! Bestimmt ist Ihre Stimme die schönste im ganzen Wald. Singen Sie mir etwas vor?“ Während er redete, ließ der Fuchs den Käse nicht aus den Augen.","es-g56-u16.r.p.2":"Der stolze Rabe öffnete den Schnabel, um zu singen… und der Käse fiel auf den Boden. Schließlich schnappte sich der Fuchs den Käse und rannte davon. Die Lehre: Glaub nicht jedem schönen Wort, das du hörst.","es-g56-u16.r.q.4.o.0":"stolz (eingebildet)","es-g56-u16.r.q.4.o.1":"hungrig","es-g56-u16.r.q.4.o.2":"traurig","es-g56-u16.r.q.4.o.3":"müde"},g={...e,...s,...n,...i,...u};export{g as default};
